programs.sol:
"""Approximate a response to dialogue delimiters and split text escapes.

Message/tool/thinking markers give the largest positive responses. A new
conversation's first message-start marker is different from a later one.
Another response occurs when a backslash is one token but the following
newline/tab escape letter is fused with the beginning of the next word.
Bare opening angle brackets and escaped quote fragments get smaller responses.
Other lexical variation is deliberately left unexplained.
"""
READS = ()

MARKERS = {
    '<|im_end|>': 2.33,
    '<tool_call>': 1.93,
    '</tool_call>': 1.90,
    '<tool_response>': 2.80,
    '</tool_response>': 2.16,
    '<think>': 1.81,
    '</think>': 0.77,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, tail = 0, '', ''
    else:
        position, previous, tail = carry[1] + 1, carry[2], carry[3]
    token = prefix.token_strings[-1]
    value = MARKERS.get(token, 0.0)
    if token == '<|im_start|>':
        value = -0.062 if position == 0 else 2.82
    elif token == 'user' and previous == '<|im_start|>':
        value = 0.594 if position == 1 else 0.04
    elif previous.endswith('\\'):
        if len(token) > 1 and token[1:].isalpha():
            if token.startswith('n'):
                value = 1.70
            # A tab in an indentation run, not an ordinary TeX command.
            elif token.startswith('t') and tail.endswith(('\\n\\', '\\t\\')):
                value = 1.90
        elif len(token) > 1 and token.startswith('"'):
            value = 0.64
    elif token.strip() == '<':
        value = 0.38
    return (doc, position, token, (tail + token)[-3:]), value

"""A sparse approximation using indefinite phrases and object-like contexts.

English rules recognize person/thing descriptions, single/whole quantities,
and selected light-verb phrases such as 'play a role' and 'make a choice'.
Chinese rules suppress single Han tokens after grammatical noun introducers.
The suppression is stronger if removing intervening particles/classifiers
joins two characters into a dictionary verb. This is only a heuristic.
Document starts have a negative baseline, with a strong exception for the
initial numeral prefix '12' and its extension '122'. State resets per document.
"""
import regex
import cedict
import wordnet
from functools import lru_cache

READS = ()
CLASSIFIERS = set(
    '个個份只首张張条條本件块塊门門口杯碗种種场場位把颗顆根朵片'
    '套段遍次扇笔筆群支台幅点點座头頭些双雙天年'
)
ASPECT = set('了过過着著完起')
POSSESSIVE = set('的之')
INTERVENING = CLASSIFIERS | ASPECT | POSSESSIVE | set(
    '一二三四五六七八九十百千万兩两幾几这這那每不没沒无無有好碎坏壞'
)


@lru_cache(None)
def is_verb(compound):
    return any(g.startswith('to ') for g in cedict.glosses(compound))


def chinese(token, tail):
    if not regex.fullmatch(r'\p{Script=Han}+', token):
        return 0.0
    # A fused possessive is treated like a separate possessive token.
    if token.startswith('的') and len(token) == 2:
        tail += '的'
        token = token[1:]
    if len(token) != 1:
        return 0.0
    if token in set('的一二三四五六七八九十了过過着著个個不没沒这這那'):
        return 0.0
    # Find a verb separated from this object by aspect/number/classifier.
    for distance, ch in enumerate(reversed(tail[-7:])):
        if distance and is_verb(ch + token):
            return -0.65
        if ch not in INTERVENING:
            break
    prev = tail[-1:]
    if prev in POSSESSIVE:
        return -0.17
    if prev in ASPECT:
        return -0.15
    if prev in CLASSIFIERS:
        return -0.06
    return 0.0


@lru_cache(None)
def verb_bases(word):
    return wordnet.base_forms(word, 'verb')


def english(word, recent):
    prev = recent[-1] if recent else ''
    earlier = set(recent[-5:])
    verbs = {base for old in recent for base in verb_bases(old)}
    strength = 0.0
    for distance, old in enumerate(reversed(recent[-3:])):
        if old in {'a', 'an'}:
            strength = max(strength, (1.0, 0.45, 0.15)[distance])
    if word == 'person':
        if prev in {'a', 'an'}:
            return 1.23
        if prev in {'one', 'any', 'every', 'each', 'another', 'some', 'no'}:
            return 0.65
        return 1.23 * strength if strength else (-0.08 if prev == 'the' else 0.0)
    if word == 'thing':
        return 1.0 if prev in {'any', 'every', 'some', 'no'} else 1.65 * strength
    if word == 'single':
        return 0.55 if prev in {'every', 'each'} else 0.38 * strength
    if word == 'whole':
        return 0.88 * strength
    if word == 'one':
        return 0.54 * strength
    if word == 'zero':
        return -0.5 * strength
    if word in {'huge', 'big'}:
        return strength * (1.1 if verbs & {'make', 'give'} else 0.65)
    if word == 'large':
        return 0.26 * strength
    if word in {'significant', 'crucial', 'important', 'major'}:
        return 0.8 * strength if 'play' in verbs else 0.0
    if word == 'role':
        return strength * (1.05 if 'play' in verbs else 0.1)
    if word == 'sense':
        return strength * (0.85 if verbs & {'get', 'give', 'make'} else 0.12)
    if word == 'choice':
        return 0.95 * strength if 'make' in verbs else 0.0
    if word == 'idea':
        return 0.85 * strength if verbs & {'get', 'give'} else 0.1 * strength
    if word == 'attention':
        return 0.8 if 'catch' in verbs else 0.0
    if word == 'living':
        if verbs & {'make', 'earn', 'pay'} or earlier & {'for', 'his', 'her'}:
            return -1.1
        return -0.6 * strength
    if word == 'need':
        return -0.5 if prev in {'a', 'an', 'no'} else 0.04
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        age, recent, tail, initial = 0, (), '', ''
    else:
        _, age, recent, tail, initial = carry
        age += 1
    word = token.strip().lower()
    value = english(word, recent) if token.startswith(' ') else 0.0
    value += chinese(token, tail)
    if age == 0:
        value = -0.1
        if token.isspace():
            value = -0.4
        if len(token) == 1 and token.isascii() and token.isdigit():
            value = -0.4
            initial = token
    elif age == 1 and initial == '1' and token == '2':
        value = -4.16
        initial = '12'
    elif age == 2 and initial == '12' and token == '2':
        value = -1.64
    carry = (doc, age, (recent + (word,))[-5:], (tail + token)[-20:], initial)
    return carry, value

programs.haiku:
"""Layer 1 MLP down-projection, component 4161: a weak, mostly quiet feature.

Plain-terms summary of what it responds to (fitted on training text):

1. Start of a document (the first token of each document; positions reset per
   document). This is the largest effect, and it depends on what the first token
   is: a number or a code keyword (import, package, #include) gives a clear
   negative value, a blank or newline a negative one, and a capitalised word
   that opens a sentence is close to zero.
2. An English word right after a singular article or determiner ("a", "an",
   "every", "any"): a small positive value in general. For the words that most
   often close such a phrase as a size/quantity/colour word or a generic noun
   ("a person", "a whole", "a huge", "a big", "a single", "a large", "a white",
   "a power", "a thing"), the value is strongly positive. After "the" the same
   words are about zero.
3. A single Chinese character that follows another Chinese character: a small
   negative value.

Everything else is predicted as 0. The component's activation is usually about
+/-0.05 and most of its variance is diffuse and token-specific, so this program
explains only a few percent of the variance.
"""

READS = ()

ARTICLES = {" a", " an", " A", " every", " any"}
# words that most often follow a singular article as a size, quantity, colour or generic noun
BIG_AFTER_ARTICLE = {
    " person", " thing", " whole", " huge", " big", " large", " single", " entire",
    " one", " power", " white", " black", " hard", " easy", " true", " role", " key",
    " head", " car",
}
# first tokens of a document that are code keywords
CODE_START = {
    "import", "package", "#include", "def", "class", "return", "using",
    "namespace", "public", "private", "static", "void", "int", "var", "let",
    "const", "function", "from",
}


def is_cjk(text):
    return any("一" <= ch <= "鿿" for ch in text)


def is_english_word(text):
    return text.startswith(" ") and len(text) > 1 and text[1:].isascii() and text[1:].isalpha()


def document_start_value(token):
    """Value at the first token of a document, from what that token is."""
    bare = token.strip()
    if bare.isdigit():
        return -0.37
    if bare in CODE_START or bare.startswith("#"):
        return -0.24
    if bare == "":
        return -0.23
    if bare[:1].isupper() and bare.isascii() and bare.isalpha():
        return -0.04
    return -0.11


def step(carry, prefix, upstream):
    t = prefix.position
    cur = prefix.token_strings[t]
    if t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]:
        return None, document_start_value(cur)
    prev = prefix.token_strings[t - 1]
    value = 0.0
    if prev in ARTICLES and is_english_word(cur):
        value = 0.5 if cur in BIG_AFTER_ARTICLE else 0.02
    elif len(cur) == 1 and is_cjk(cur) and is_cjk(prev):
        value = -0.02
    return None, value

"""Study-subject detector (v6).

Fires on the words that name what an experiment studied: whole organisms and people
(rats, mice, rabbits, patients, participants, women in a cohort), experimental material
(samples, cells, strains, tissues), and the group/design words around them (group,
control, treated, studied). Its size is scaled up when the text so far is an experimental
description (a decaying count of such words plus 'of', 'from', 'were'...). Figure and
table references, and molecular-biology words, push it slightly negative.
"""
ORGANISMS = {
    'rat', 'rats', 'mouse', 'mice', 'rabbit', 'rabbits', 'chicken', 'chickens', 'animal',
    'animals', 'sheep', 'cats', 'pigs', 'pig', 'goat', 'calves', 'pups', 'plants', 'barley',
    'maize', 'bean', 'vine', 'wild', 'newborn', 'pregnant', 'mutant', 'mutants', 'strain',
    'strains', 'patient', 'patients', 'participant', 'participants', 'subject', 'subjects',
    'women', 'men', 'human', 'humans', 'cohort', 'children', 'individuals', 'adults',
    'females', 'males', 'female', 'male',
}
MATERIAL = {'sample', 'samples', 'cells', 'cell', 'lines', 'line', 'tissue', 'tissues',
            'specimens', 'extracts', 'isolated', 'cultured'}
DESIGN = {'group', 'groups', 'control', 'treated', 'study', 'studies', 'experimental',
          'experiment', 'experiments', 'studied', 'collected', 'selected', 'subjected',
          'sacrificed', 'tested', 'examined', 'untreated'}
FIGURES = {'figure', 'figures', 'fig', 'table', 'tables', 'supplementary'}
MOLECULAR = {'protein', 'dna', 'receptor', 'binding', 'expression', 'gene', 'genes', 'mrna',
             'enzyme', 'positive', 'negative', 'correlated', 'ldl'}
FUNCTION_WORDS = {'of', 'from', 'were', 'with', 'and', 'to', 'at', 'in'}
CONTEXT_WORDS = ORGANISMS | MATERIAL | DESIGN | FUNCTION_WORDS
READS = ()

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    ctx, last_doc = carry if carry is not None else (0.0, doc)
    if doc != last_doc:
        ctx = 0.0
    word = prefix.token_strings[-1].strip().lower()
    gate = min(1.0, ctx / 3.0)
    value = 0.0
    if word in ORGANISMS:
        value = 0.36 + 1.3 * gate
    elif word in MATERIAL:
        value = 1.15 * gate
    elif word in DESIGN:
        value = 0.23 + 0.6 * gate
    elif word in FIGURES:
        value = -0.08 - 0.7 * gate
    elif word in MOLECULAR:
        value = -0.1 - 0.3 * gate
    elif word.isdigit():
        value = 0.1 * gate
    ctx = 0.9 * ctx + (1.0 if word in CONTEXT_WORDS else 0.0)
    return (ctx, doc), value

programs.sol:
"""A local lexical approximation, not a sentiment or topic detector.

Its largest responses mark article metadata after 本文 ('this article').
It also recognizes selected 本 compounds, several Korean compounds, and
Chinese 'the following is a ...' introductions. Token boundaries matter.
A coarse frequency/shape baseline handles document starts. Other interior
contexts return zero. This deliberately omits the long tail of other
collocations and word-specific background responses.
"""
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

# 本: Japanese compounds ('real', 'main', 'original') and Chinese references
# to 'this' product, activity, section, regulation, etc. Signs are lexical.
AFTER_BEN = {
    '格': 4.1, '名': 2.7, '気': 1.5, '物': 1.9,
    '番': 1.6, '音': 1.2, '家': 1.1, '記事': 1.4,
    '组': 1.2, '篇文章': 1.0,
    '質': -0.75, '末': -0.8, '業': -2.3,
    '品': -2.1, '节': -1.6, '规定': -1.2,
    '活动': -1.3, '实验': -1.1, '内容': -3.0,
}

# Article-reference constructions grouped by the kind of label.
ARTICLE_LOCATION = {'来源', '链接', '地址', '目录'}
ARTICLE_INDEXING = {'关键词', '标签'}
ARTICLE_CONTENT = {'转载', '全文', '图片', '内容', '观点', '来自', '原创'}
ARTICLE_DESCRIPTION = {
    '作者', '介绍', '包含', '阅读', '版权', '著作权', '仅代表', '及',
}

# Complete selected two-syllable Korean words: main, attention, topic,
# first/best/final, summary, sudden/all-out, major, and reservation.
KOREAN = {
    ' 주': {'요': 3.1, '목': 1.4, '제': 1.0},
    ' 최': {'초': 1.5, '선': 1.0, '종': 1.0},
    ' 요': {'약': 3.7},
    ' 전': {'격': 3.9, '공': 2.3},
    ' 예': {'약': 1.2},
}


@lru_cache(maxsize=8192)
def initial_value(token):
    """Initial word fragments tend negative; common English words less so."""
    word = token.strip()
    if len(word) > 1 and word.isascii() and word.isalpha():
        frequency = zipf_frequency(word, 'en')
        return min(0.1, -0.7 + 0.5 * max(0.0, frequency - 5.3))
    if word.isalpha() and not word.isascii():
        return -0.3
    if token == ' ':
        return 0.25
    if token.isspace() and ('\n' in token or len(token) >= 3):
        return -0.45
    if token.startswith('/*'):
        return -1.6
    if token == '<|endoftext|>':
        return -2.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, position, label_strength = '', 0, 0.0
    else:
        previous = carry[1]
        position = carry[2] + 1
        label_strength = carry[3]

    value = initial_value(token) if position == 0 else 0.0
    next_label_strength = 0.0
    if previous == '本':
        value = AFTER_BEN.get(token, 0.0)
    elif previous == '本文':
        if token in ARTICLE_LOCATION:
            value = 9.0
        elif token in ARTICLE_INDEXING:
            value = 11.0
        elif token == '摘要':  # abstract/summary
            value = 13.5
        elif token in ARTICLE_CONTENT:
            value = 3.5
        elif token in ARTICLE_DESCRIPTION:
            value = 1.7
        next_label_strength = value
    elif previous in KOREAN:
        value = KOREAN[previous].get(token, 0.0)
    elif previous in {'以下', '下面'} and token == '是一':
        value = -2.5
    elif previous == '興' and token == '味':  # interest
        value = 0.7
    elif previous == '··' and token == '··':  # dotted filler
        value = -1.1

    # Metadata labels have a smaller response on the following colon.
    if token == '：' and label_strength:
        value = 0.2 * label_strength
    if position == 1 and previous == '1' and token == '2':
        value = 3.3
    return (doc, token, position, next_label_strength), value

"""Approximate sparse formatting responses at document openings.

The colon in initial 'Title:' is positive. Initial empty // comment
lines, <! declaration openers, the bracket in initial {[, and an
uninterrupted opening run of bare carriage returns are negative.
Ordinary opening ASCII words and digits get a small negative baseline;
later text is near zero. Reset state at each document or row boundary.
Smaller token-specific variation is not modeled.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, first, only_cr = 0, token, True
    else:
        position, first, only_cr = carry[1] + 1, carry[2], carry[3]
    only_cr = only_cr and token == "\r"
    value = -0.002
    if position == 0:
        word = token.strip()
        if word.isascii() and word.isalpha():
            value = -0.23 if word[0].isupper() else -0.14
        elif word.isascii() and word.isdecimal():
            value = -0.16
    elif position == 1:
        value = -0.006
    if position == 1 and first == 'Title' and token == ':':
        value = 18.105
    elif position == 0 and token == '//\n':
        value = -121.187
    elif position == 0 and token == '<!':
        value = -159.3
    elif position == 1 and first == '{' and token == '[':
        value = -15.6
    elif only_cr:
        value = -65.819
    return (doc, position, first, only_cr), value

"""Coarse document-boundary and split-character effects, not a topic detector.

At document starts, space fragments longer than one are positive, especially
3, 7, 11, ... spaces: fragments of four-space indentation. Bare lowercase
words and digits 0/1 are negative. Opening Title: metadata has a large
positive colon response; the numeric prefix 12 has a negative one. Small
initial-script and whitespace averages cover other boundary effects.

Split four-byte emoji are negative, while split Hangul and Gurmukhi tippi
are positive on average. Most positions stay near zero. Individual rare-
kanji responses are not reconstructed.
"""
import codecs
import math
import regex

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos, opening, pending = 0, '', b''
    else:
        _, pos, opening, pending = carry
    s = prefix.token_strings[-1]
    b = prefix.token_bytes[-1]
    value = -0.003
    if pos == 0:
        opening = s
        if s and not s.strip(' '):
            n = len(s)
            if n == 1:
                value = -0.136
            elif n % 4 == 3:
                value = 1.4 + 0.846 * math.exp(-(n - 3) / 5)
            else:
                value = 0.75
        elif s and not s.strip('\u00a0'):
            value = -1.03
        elif s.startswith('\n') and not s.strip():
            value = -0.24
        elif s.isascii() and s.isalpha() and s.islower():
            value = -0.23
        elif s in ('0', '1'):
            value = -0.50
        elif regex.match(r'\p{Script=Han}', s):
            value = -0.18
        elif regex.match(r'\p{Script=Arabic}', s):
            value = -0.45
        if s == 'Title':
            value = -1.297
    elif pos == 1:
        if opening == 'Title' and s == ':':
            value = 5.086
        elif opening == '1' and s == '2':
            value = -2.848

    # Decode across token boundaries, retaining only unfinished UTF-8 bytes.
    continuing = bool(pending) and b and 0x80 <= b[0] < 0xC0
    raw = pending + b
    decoded, used = codecs.utf_8_decode(raw, 'replace', False)
    pending = raw[used:]
    if continuing and decoded:
        ch = decoded[0]
        if ord(ch) > 0xFFFF and regex.fullmatch(r'\p{Emoji}', ch):
            value = -0.30
        elif ch == '\u0a70':  # Gurmukhi tippi, a nasalization mark.
            value = 0.85
        elif regex.fullmatch(r'\p{Script=Hangul}', ch):
            value = 0.11
        elif regex.fullmatch(r'\p{Script=Han}', ch):
            value = 0.034
        else:
            value = 0.03
    elif continuing and pending:
        # Two bytes can already locate an unfinished Hangul syllable.
        low = pending.ljust(3, b'\x80').decode('utf-8', 'ignore')
        if regex.fullmatch(r'\p{Script=Hangul}', low):
            value = 0.10
    return (doc, pos + 1, opening, pending), value

"""A sparse surface-form approximation, not a single semantic detector.

Recognize completions of stock web labels and some document-opening syntax.
Between those spikes, use small spelling/typography biases: v/q/u/w initials,
backticks, tabs, checkmarks and middle-dot runs, plus a few English
grammatical classes. Keep only a short text tail
and the previous token's bytes, resetting both at document boundaries.
"""
import unicodedata

READS = ()

WH_WORDS = frozenset('which who whom whose where when'.split())
NEGATORS = frozenset('no not never none neither without'.split())
OBLIGATION_MODALS = frozenset('must should shall ought'.split())

# Complete labels, with the response on the token that finishes the label.
LABELS = {
    'Wiki User': 1.15,
    'View Full Document': 0.90,
    'Similar Homework Help Questions': 0.93,
    'Latest reply': 0.82,
    '<issue_start><issue': 1.457,
    '<issue_comment>Title': 0.546,
    '<issue_comment>Title:': 0.268,
}


def background(token):
    word = token.strip()
    lower = word.lower()
    value = -0.0016
    if len(word) >= 2 and set(word) == {'·'}:
        return -0.394
    if '✓' in word:
        return 0.143 if token.startswith(' ') else 0.050
    if '`' in word:
        return -0.067 if token.startswith(' ') else -0.025
    if '\t' in token:
        return -0.025
    if lower.startswith('v'):
        value -= 0.041
    elif lower.startswith('q'):
        value -= 0.031
    elif lower.startswith('u'):
        value -= 0.014
    elif lower.startswith('w'):
        value -= 0.009
    elif word.startswith('+'):
        value += 0.030
    if lower in WH_WORDS:
        value += 0.018
    elif lower in NEGATORS:
        value -= 0.014
    elif lower in OBLIGATION_MODALS:
        value += 0.033
    elif lower == 'would':  # Conditional auxiliary.
        value -= 0.046
    elif lower in ('here', 'there'):  # Deictic place words.
        value += 0.029
    if word and unicodedata.name(word[0], '').startswith(
        ('HIRAGANA', 'KATAKANA')
    ):
        value -= 0.010
    if token in ('<tool_call>', '<think>'):
        value = -0.071
    elif token == '<|im_start|>':
        value = -0.029
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, position, previous_bytes = '', 0, b''
    else:
        _, text, position, previous_bytes = carry
    token = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    old = text
    text = (text + token)[-100:]
    value = background(token)

    for label, response in LABELS.items():
        if text.endswith(label) and not old.endswith(label):
            value = response
            break

    if position == 0:
        if token == 'Title':
            value = -0.590
        elif token == 'Uploaded':
            value = -0.527
        elif token in ('import', 'from', 'package'):
            value = 0.60
        elif token == 'using':
            value = 0.771
        elif token == 'def':
            value = -0.807
        elif token == 'class':
            value = -0.161
        elif token == '#include':
            value = 0.568
        elif token in ('#pragma', '#ifndef'):
            value = 1.02
        elif token == '//':
            value = 0.166
        elif token == '/*':
            value = 0.261
        elif token == '"""':
            value = 1.054
        elif token == '--':
            value = -1.107
        elif token == '<!':
            value = 3.21
    elif position == 1:
        if old == 'Title' and token == ':':
            value = -3.035
        elif old == 'Uploaded' and token == ' by':
            value = -1.65
        elif old == '(function' and token == ' ()':
            value = 1.75
        elif old == 'Hy' and token == 'dro':
            value = 1.52

    # The incomplete UTF-8 prefix shared by 貝 and neighbouring Han characters.
    if previous_bytes + raw == ' 貝'.encode('utf-8')[:-1]:
        value = 0.645
    return (doc, text, position + 1, raw), value

"""A repetition-based approximation, strongest on numbered lines.

Track decimal prefixes at the beginnings of lines and recurring adjacent token
pairs. Matching the previous line's number prefix gets a large positive value;
other recurring text gets a smaller one, especially at a line's beginning.
A separate token-shape baseline handles the first token of each document.
This deliberately leaves token-specific lexical variation unexplained.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', '', '', '', '', {})
    _, position, line, digits, number_start, prior_number, previous, pairs = carry

    digit = len(token) == 1 and token in '0123456789'
    if digit and not digits:
        number_start = line
    matching_number = (digit and not number_start.strip()
                       and prior_number.startswith(digits + token))
    repeats = pairs.get((previous, token), 0)
    spaces = len(line) - len(line.rstrip(' '))
    text = token.strip()
    letters = any(ch.isalpha() for ch in text)
    punctuation = bool(text) and not any(ch.isalnum() for ch in text)

    if matching_number:
        if spaces >= 2:
            value = 0.45 if repeats >= 3 else 0.29
        else:
            value = 0.25
    elif position == 0:
        if not letters:
            value = 0.008
        elif len(token) <= 2:
            value = -0.114
        else:
            value = -0.143 if token.startswith(' ') else -0.335
    elif repeats >= 3:
        if token.isspace():
            value = -0.005
        elif punctuation:
            value = -0.014
        elif len(line) <= 2:
            value = 0.182
        elif spaces >= 2:
            value = 0.128
        elif digit:
            value = 0.075
        else:
            value = 0.04 if len(line) <= 33 else 0.012
    elif digit:
        value = -0.025 if repeats == 0 else 0.03
    else:
        value = 0.0

    pairs[previous, token] = repeats + 1
    digits = digits + token if digit else ''
    if '\n' in token:
        completed = (line + token).split('\n')[-2]
        match = re.match(r' *([0-9]+)[\t ]', completed)
        prior_number = match.group(1) if match else ''
        line = token.rsplit('\n', 1)[-1]
    else:
        line = (line + token)[-300:]
    return (doc, position + 1, line, digits, number_start,
            prior_number, token, pairs), value

programs.haiku:
"""Arabic vowel marks, and broken bytes in Arabic or Hebrew text.

This component writes a strong signal when the model reads Arabic-script text that has
vowel marks (harakat) on its letters. It fires on:
- the marks themselves: fatha, damma and kasra most, then tanween, then shadda and sukun;
- the stray single bytes (shown as U+FFFD) that a broken multi-byte letter leaves behind,
  when they come within a few tokens after an Arabic or Hebrew letter. Only some of
  them fire, so this is a moderate value.
Otherwise it is near zero, except the first token of each document, which sits slightly
below zero.

Predicted activation:
- a token holding an Arabic harakat gets that mark's typical value;
- a broken-byte token within 8 tokens after an Arabic or Hebrew letter, in the same
  document, gets a moderate value;
- the first token of a document gets a small negative value;
- every other token gets 0.
"""

READS = ()

# Typical activation for each Arabic vowel mark, from training text.
MARK_VALUE = {
    "ً": 7.0,  # fathatan (tanween fath)
    "ٌ": 7.0,  # dammatan
    "ٍ": 7.0,  # kasratan
    "َ": 9.0,  # fatha
    "ُ": 11.0,  # damma
    "ِ": 9.0,  # kasra
    "ّ": 4.0,  # shadda
    "ْ": 3.0,  # sukun
}
BROKEN_BYTE_VALUE = 2.5
DOCUMENT_START_VALUE = -0.2
RECENT = 8  # tokens to look back for an Arabic or Hebrew letter


def is_arabic_or_hebrew(ch):
    return "֐" <= ch <= "׿" or "؀" <= ch <= "ۿ"


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if len(prefix.token_strings) == 1 or prefix.document_ids[-2] != doc:
        return None, DOCUMENT_START_VALUE
    marks = [MARK_VALUE[c] for c in tok if c in MARK_VALUE]
    if marks:
        return None, max(marks)
    if "�" in tok:
        lo = max(0, len(prefix.token_strings) - 1 - RECENT)
        for i in range(len(prefix.token_strings) - 2, lo - 1, -1):
            if prefix.document_ids[i] != doc:
                break
            if any(is_arabic_or_hebrew(c) for c in prefix.token_strings[i]):
                return None, BROKEN_BYTE_VALUE
    return None, 0.0

programs.sol:
"""A local detector for truth substitutes and qualifications.

Large negative responses: 'if so', 'think so', 'perhaps not', 'if yes'.
Smaller responses: intensifying 'so' and negated degree words such as
'not quite' and 'not necessarily'.  Auxiliary negation ('does not') and
connective ', so' stay near zero; indented code 'if not' is weaker than
sentence-initial 'If not'.  Mandarin conditional/copular phrases get a
parallel set of rules, using simplified/traditional conversion.

This approximates the prominent negative responses, not every fluctuation
of the component.  Unlisted tokens return zero.  Context is at most two
preceding tokens, never crossing a document boundary.
"""
from functools import lru_cache
import wordnet
import opencc

READS = ()
AUXILIARIES = set('be is are was were am been being do does did have has had '
                  'can could will would shall should must'.split())
BELIEF = set('think hope assume believe suppose suspect guess'.split())
APPEARANCE = set('seem appear'.split())
SPEECH = set('say tell'.split())
NEGATORS = {'not', "'t", '’t', 'never'}
SIMPLIFY = opencc.OpenCC('t2s')
CONDITIONALS = {'如果', '假如', '假若', '倘若', '要是', '若'}
CONCESSIVES = {'虽然', '尽管', '即使', '哪怕', '无论', '不论', '不管'}
CHINESE_BELIEF = {'认为', '以为', '相信', '怀疑', '觉得', '发现'}


@lru_cache(maxsize=4096)
def simplified(text):
    return SIMPLIFY.convert(text)


def chinese(token, previous):
    s, p = simplified(token.strip()), simplified(previous.strip())
    # Chinese packs the condition and truth predicate into one token as well.
    for condition in CONDITIONALS:
        if s.startswith(condition):
            tail = s[len(condition):]
        else:
            tail = s if p == condition else ''
        if tail == '真是':
            return -2.5
        if tail == '是':
            return -6.0 if condition == '如果' else -2.5
        if tail in {'没有', '不', '有'}:
            return -4.4 if condition == '如果' and tail != '有' else -2.2
    if s.endswith('是'):
        qualifier = s[:-1] or p
        if qualifier in CONCESSIVES:
            return -4.5 if qualifier == '虽然' else -2.3
        if qualifier in {'毕竟', '只要'}:
            return -3.4
        if qualifier in {'真', '确实', '果然', '显然'}:
            return -0.6
        if qualifier in CHINESE_BELIEF:
            return -1.1
        if qualifier in {'算', '究竟', '竟然', '当然'}:
            return -0.5
        if qualifier == '不':
            return -0.35
    if s == '如此':
        return -1.8
    return 0.0


@lru_cache(maxsize=4096)
def bases(word):
    return set(wordnet.base_forms(word)) | {word}


def predict(token, previous='', before_previous=''):
    if not token.isascii():
        value = chinese(token, previous)
        if value:
            return value
    w = token.strip().lower()
    p = previous.strip().lower()
    pp = before_previous.strip().lower()
    if w in {'not', 'so', 'yes'}:
        if token.strip() == 'So':
            return 0.0
        if not p:
            return 0.1 if w == 'yes' else -0.8
        if not token.startswith((' ', '\n')) and p and w == 'so':
            return 0.0
        if p == 'if':
            if w == 'so':
                return -10.2
            if w == 'yes':
                return -7.4 if previous.strip() == 'If' else -4.0
            if previous.strip() == 'If':
                return -6.4
            if before_previous.isspace():  # indented source-code 'if not'
                return -1.9
            if pp.endswith((',', ';', '?')):
                return -4.8
            return -3.0
        b = bases(p) if p.isalpha() else {p}
        if b & BELIEF:
            return -10.8 if w == 'so' and 'think' in b else -5.5
        if p in {'maybe', 'perhaps'}:
            return -6.0
        if p in {'probably', 'certainly', 'hopefully', 'unfortunately'}:
            return -6.2 if previous.strip() == 'Probably' else -3.2
        if w == 'not':
            if p in AUXILIARIES or p in {"'s", '’s', "'m", '’m'}:
                return 0.09
            if p in {'may', 'might'}:
                return -0.2
            if p in {'although', 'though'}:
                return -1.9
            if p == 'why':
                return -1.6
            if p in {'but', 'so', 'unless', 'whether'}:
                return -0.75
            if p in {'when', 'while', 'as'}:
                return -0.4
            if p in {'possibly', 'likely'}:
                return -1.7
            if p.endswith('ly') or b & APPEARANCE:
                return -1.5
            if b & {'decide', 'choose', 'prefer', 'refuse', 'forget'}:
                return -1.3
            return -0.15
        if w == 'yes':
            return 0.1
        # Distinguish predicative/intensifying 'so' from connective ', so'.
        if b & APPEARANCE:
            return -4.8
        if b & SPEECH:
            return -3.4
        if p in {'even', 'much', 'especially', 'unless'}:
            return -4.7
        if p in {'more', 'less', 'enough', 'not', 'being', 'remain', 'become'}:
            return -2.5
        if p in {'be', 'been'}:
            return -1.7
        if p in {'is', 'was', 'am', "'s", '’s', "'m", '’m', 'that', 'just'}:
            return -1.0
        if p in {'are', 'were', 'do', 'does', 'did', 'doing', 'done'}:
            return -0.45
        if ',' in p or p in {'and', 'or'}:
            return 0.17
        return -0.3
    if w in {'quite', 'necessarily', 'exactly', 'really', 'fully',
             'particularly', 'yet', 'currently', 'even'}:
        if p in NEGATORS:
            strength = {'quite': 2.8, 'necessarily': 1.9, 'exactly': 1.8,
                        'really': 1.3, 'fully': 0.5, 'particularly': 0.8,
                        'yet': 1.7, 'currently': 1.0, 'even': 0.7}[w]
            if p != 'not':
                strength *= 0.4
            elif pp in AUXILIARIES or pp in {'may', 'might'}:
                if w in {'quite', 'fully'}:
                    strength *= 0.85
                elif w in {'yet', 'currently'}:
                    strength *= 0.1
                else:
                    strength *= 0.4
            if previous.strip() == 'Not':
                strength *= 1.5
            return -strength
        if w == 'particularly' and p == 'more':
            return -1.3
        return {'quite': -0.13, 'necessarily': 0.1, 'exactly': 0.15,
                'really': 0.03, 'fully': 0.0, 'particularly': -0.04,
                'yet': 0.1, 'currently': 0.1, 'even': 0.03}[w]
    return 0.0


def step(carry, prefix, upstream):
    t = prefix.position
    doc = prefix.document_ids[-1]
    p = prefix.token_strings[-2] if t and prefix.document_ids[-2] == doc else ''
    pp = (prefix.token_strings[-3]
          if t > 1 and prefix.document_ids[-3] == doc else '')
    return None, predict(prefix.token_strings[-1], p, pp)

programs.haiku:
"""Layer-1 MLP down_proj component 4173: a negative "stand-in negation / answer word" detector.

The component is quiet almost everywhere. It goes negative on a short word that replies to
or completes a condition, without a verb of its own:
  * the elliptical reply after "if": "If so" (about -10), "If yes" (-6), "If not" (-4);
  * "not" right after a hedge or condition word: "maybe not", "perhaps not", "hopefully
    not", "certainly not", "though not" (-2 to -6), and "but not" (-0.7);
  * "so" standing in for a clause: "I think so" (-11), "I hope so", "seems so", "say so" (-4);
  * "so" as a degree word after be/is/was/not ("be so", "not so": -2);
  * a word right after a bare "not": "not quite", "not necessarily", "not exactly" (-2);
  * Chinese conditional copulas ("如果是" if it is, "如果没有", "若是", "毕竟是", ...), -2 to -6;
  * a run of middle dots "··" (a leader), a constant -0.7 (one rare corpus case).
Ordinary negation ("is not", "does not", "may not", ", not", "and not") and the conjunction
", so" stay near zero.
"""

READS = ()

AUXILIARY = {"is", "are", "was", "were", "do", "does", "did", "will", "would", "can",
             "could", "should", "may", "might", "must", "have", "has", "had", "am", "be",
             "'s", "'re", "'m", "'t", "’s", "’t", "’re", "’m", "n't"}
HEDGE_BEFORE_NOT = {"if", "maybe", "perhaps", "hopefully", "certainly", "though", "usually",
                    "assume", "hope"}
CLAUSE_STAND_IN = {"think", "thought", "hope", "hoped", "hopes", "seems", "seemed", "say",
                   "said", "guess", "believe", "expect", "suppose", "especially", "even"}
DEGREE_PREV = {"be", "is", "was", "been", "being", "not", "more", "why"}
HEDGES = {"quite", "necessarily", "exactly", "particularly", "really", "entirely", "fully"}
ZH_CONDITIONAL = {"如果是": -6.0, "如果没有": -4.7, "若是": -2.1, "毕竟是": -3.7,
                  "虽然是": -4.9, "如果不": -3.8, "只要是": -3.2, "不论是": -1.7,
                  "无论是": -2.5, "不管是": -2.7, "如有": -1.7}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    same_doc = len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    value = 0.0
    if raw in ZH_CONDITIONAL:
        value = ZH_CONDITIONAL[raw]
    elif raw == "··":
        value = -0.7
    elif prev == "if" and word in ("so", "not", "yes"):
        value = {"so": -10.0, "yes": -6.0, "not": -4.0}[word]
    elif word == "so" and prev == "think":
        value = -11.0
    elif word == "so" and prev in CLAUSE_STAND_IN:
        value = -4.0
    elif word == "so" and prev in DEGREE_PREV:
        value = -2.0
    elif word == "not" and prev in HEDGE_BEFORE_NOT:
        value = -5.0
    elif word == "not" and prev in ("but", "why", "still", "when"):
        value = -1.0
    elif word in HEDGES and prev == "not":
        value = -2.0
    return carry, float(value)

programs.sol:
"""Predict formatting-related responses, chiefly newlines in lowercase running text.

Lowercase-letter density in the current and preceding line provides a soft
measure of line continuation. Capitals and short preceding lines weaken it;
a bare newline is treated differently from punctuation merged with a newline.
The assistant header, lowercase "posted by" bylines, and AM/PM clock markers
have separate rules. Other tokens are zero. History is limited to 1200
characters and resets at document boundaries. This omits small lexical effects.
"""
import re

READS = ()


def unit(x):
    return max(0.0, min(1.0, x))


def lowercase_fraction(line):
    return sum(c.islower() for c in line) / max(1, len(line))


def line_break(token, text):
    lines = text.split('\n')
    line = lines[-1]
    previous = lines[-2] if len(lines) > 1 else ''
    lower = lowercase_fraction(line)
    upper = sum(c.isupper() for c in line) / max(1, len(line))
    preceding_text = min(len(previous.split()) / 5.0, 1.0)
    if token == '\n':
        if line == 'assistant':
            return 0.5
        if upper <= 0.002:
            if not re.search(r'\w$', line):
                return 0.045
            density = unit((lower - 0.65) / 0.30)
            continuation = unit((lowercase_fraction(previous) - 0.50) / 0.30)
            return 0.095 + density * (0.66 + 1.32 * continuation)
        density = unit((lower - 0.55) / 0.25)
        few_capitals = unit((0.10 - upper) / 0.08)
        return -0.01 + 0.56 * density * preceding_text * few_capitals
    if upper > 0.002:
        return -0.02
    density = unit((lower - 0.60) / 0.25) ** 2
    bare_break = float(not token.strip())
    return density * (0.10 + 0.41 * bare_break + 0.19 * preceding_text)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, clocks = '', 0
    else:
        text, clocks = carry[1:]
    token = prefix.token_strings[-1]
    value = line_break(token, text) if '\n' in token or '\r' in token else 0.0
    line = text.rsplit('\n', 1)[-1]
    if token == 'posted' and not line.strip():
        value = 6.7
    elif token == ' by' and line.strip() == 'posted':
        value = 7.5
    elif token in (' AM', ' PM'):
        time = re.search(r'\b\d{1,2}\s*:\s*\d{2}(?::\d{2})?$', text)
        if time:
            dated = re.search(r'\b(?:19|20)\d{2}\b', text[-120:])
            if dated:
                value = -3.6 if len(text) < 100 else -2.7
                if time.group().count(':') == 2:
                    value -= 0.6
            else:
                value = -1.6 if clocks == 0 else -1.1
            clocks += 1
        elif re.search(r'\b(?:[1-9]|1[0-2])$', text):
            value = -0.35
    return (doc, (text + token)[-1200:], clocks), value

"""Recognize mapping keys and method/function declaration syntax.

Colons after keys following an opening brace or comma are strong positives;
block-ending colons and function arrows are not. Quoted keys are strongest
just after an opening brace. Formal `self`, access/declaration keywords and
method decorators give smaller positives. NUL after a letter/digit and
middle-dot leaders are separate positive patterns. A document-initial
`Title:` label is negative, and initial `using` is positive. A rough brace
count and a short trailing text buffer reset at each document boundary.
"""
import re

READS = ()
KEY = re.compile(r'([{,])\s*(?:\d+\s+)?(?:[-+]\s*)?(?:[A-Za-z_$][\w$]*|\d+)$')
QUOTED = re.compile(r'''([{,])\s*(?:\d+\s+)?(?:[-+]\s*)?\\?["'][^"'\n]*$''')
PHP_KEY = re.compile(
    r'''(?:array\(|[\[,{])\s*(?:\d+\s+)?(?:[-+]\s*)?(?:'[^'\n]*'|"[^"\n]*")$'''
)
INDENT = re.compile(r'\s*(?:\d+\s+)?(?:[-+]\s*)?')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, depth = '', 0
    else:
        recent, depth = carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip()
    before = recent.replace('\\n', '\n').replace('\\t', '\t')
    line = before.rsplit('\n', 1)[-1]
    leading = token[:len(token) - len(token.lstrip())]
    line = (line + leading).rsplit('\n', 1)[-1]
    code_line = INDENT.sub('', line, count=1).strip()
    value = 0.0

    if token == '\x00':
        value = 1.44 if recent[-1:].isalnum() else 0.20
    elif len(token) >= 2 and not token.strip('·'):
        value = 1.79
    elif token in ('":', "':", '\\":'):
        match = QUOTED.search(before)
        if match:
            value = 1.75 if match[1] == '{' else 1.25
            if token.startswith('\\'):
                value += 0.30
    elif token in (':"', '":"', ":'"):
        value = 0.60
    elif token == ' =>' and PHP_KEY.search(before):
        value = 1.50
    elif token in (':', '_:', ']:'):
        key = KEY.search(before)
        type_block = re.search(
