        in_parameters = re.search(r'\([^(){}]*$', before)
        if key and depth > 0 and not type_block and not in_parameters:
            value = 1.80
        elif token == ']:' and re.search(r'[{,]\s*\[[^\n]*$', before):
            value = 1.80
        elif recent == 'Title':
            value = -2.67
    elif word == 'using' and not recent:
        value = 1.66
    elif word in ('public', 'protected', 'private') and not code_line:
        value = 0.82 if word != 'private' else 0.28
        if not token[:1].isspace():
            value *= 0.55
    elif word in ('def', 'func', 'fn', 'function'):
        if not code_line:
            value = 0.38 if token[:1].isspace() else (
                0.52 if word in ('def', 'fn') else 0.77
            )
        elif word == 'function' and code_line in (
            'public', 'protected', 'private', 'static', 'export',
            'public static', 'protected static', 'export async',
        ):
            value = 1.20
    elif word in ('static', 'override') and code_line in (
        'public', 'protected', 'private', 'internal',
    ):
        value = 0.65
    elif word == '@Override' or (word == 'Override' and recent.endswith('@')):
        value = 0.84
    elif word in ('staticmethod', 'classmethod') and recent.endswith('@'):
        value = 1.30 if word == 'staticmethod' else 0.80
    elif word in ('(self', 'self') and re.search(r'\b(def|fn)\b', line):
        value = 1.00
    depth = max(0, depth + token.count('{') - token.count('}'))
    return (doc, (recent + token)[-600:], depth), value

"""A weak word-shape/formatting signal, strongest at document starts.

Document-initial whitespace, Cyrillic and -ed/-ing endings get negative
values. Extremely frequent English words and code markers have exceptions.
Elsewhere only small punctuation, script and word-class offsets remain.
These are group averages, not predictions of individual words' variation.
"""
from functools import lru_cache
import unicodedata
import regex
from wordfreq import zipf_frequency

READS = ()
QUANTIFIERS = frozenset('all any some no more most much many each every '
                        'few other such both either neither'.split())


@lru_cache(maxsize=32768)
def predict(token, first):
    word = token.strip()
    lower = word.lower()
    if first:
        if token[-1:].isspace():
            return -0.16 if '\n' in token else -0.22
        if word.isalpha():
            if zipf_frequency(lower, 'en') > 7.4:
                return 0.15 if word.istitle() else -0.008
            if regex.search(r'\p{Script=Cyrillic}', word):
                return -0.23
            if lower.endswith('ed'):
                return -0.24
            if lower.endswith('ing'):
                return -0.14
            return -0.088
        if '#' in token:
            return 0.08
        if '_' in token:
            return 0.038
        return -0.024

    if word.startswith('<|'):
        return -0.012
    if lower in QUANTIFIERS:
        return -0.009
    if regex.search(r'\p{Script=Katakana}', word):
        return -0.010
    if word.isalpha() and lower.endswith('ed'):
        return -0.0055
    if word and all(unicodedata.category(c)[0] in 'PS' for c in word):
        if '|' in word:
            return -0.012
        if '/' in word or '\\' in word:
            return 0.008
        if ':' in word or ';' in word:
            return 0.007
        return 0.002
    return -0.001


def step(carry, prefix, upstream):
    first = (prefix.position == 0
             or prefix.document_ids[-1] != prefix.document_ids[-2])
    return None, predict(prefix.token_strings[-1], first)

