import re
from functools import lru_cache
import wordnet

READS = ()

@lru_cache(maxsize=4096)
def is_verb(word):
    return 'verb' in wordnet.parts_of_speech(word)


def any_value(text, context):
    if not text[:1].isspace():
        return 0.03
    words = re.findall(r"[a-z]+(?:'[a-z]+)?",
                       context.lower().replace("’", "'"))
    last = words[-1] if words else ''
    negative = any(w in {'not', 'never', 'no', 'hardly', 'without'}
                   or w.endswith("n't") for w in words[-4:-1])
    if last == 'without':
        value = 2.8
    elif last in {'no', 'not'} or last.endswith("n't"):
        value = 0.75
    elif last in {'there', 'are'}:
        value = 0.75
    elif last in {'is', 'was', 'were', 'be'}:
        value = 0.7 if negative or 'there' in words[-4:] else 0.02
    elif last in {'have', 'has', 'had'}:
        value = 1.3 if negative else 0.55
        if len(words) > 1 and words[-2] in {'can', 'could', 'to'}:
            value = 0.2
    elif is_verb(last):
        value = 1.15 if negative else 0.25
    elif last == 'if':
        value = 0.2
    else:
        value = 0.02
    if text.strip().isupper():
        value = 0.55 * value + 0.08
    elif text.strip()[0].isupper():
        value = 0.06
    return value


def predict(text, context):
    if text.strip().lower() == 'any':
        return any_value(text, context)
    if text == '任何':  # any
        return 1.5
    if text == '手':  # hand
        return 1.0
    if text == '手机':  # mobile phone
        return 1.6
    if text == '肉':  # meat / flesh
        return 2.2 if context.endswith('果') else 4.8  # fruit pulp
    if text == ' android' and re.search(r'\bimport\s*$', context):
        return 1.28
    return -0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_doc = carry is not None and carry[0] == doc
    context = carry[1] if same_doc else ''
    raw_tail = carry[2] if same_doc else b''
    token = prefix.token_bytes[-1]
    raw_tail = (raw_tail + token)[-16:]
    text = prefix.token_strings[-1]
    value = predict(text, context)

    # A byte tokenizer can split one character over several tokens. Decode
    # the short byte tail, rather than mistaking a continuation for '�'.
    if len(token) == 1 and 0x80 <= token[0] < 0xC0:
        decoded = raw_tail.decode('utf8', 'replace')
        char = decoded[-1]
        spaced = len(decoded) > 1 and decoded[-2].isspace()
        if char == '肉':
            value = 4.8 + (2.0 if spaced else 0.0)
        elif char == '手':
            value = 1.0 + (0.6 if spaced else 0.0)
        elif spaced and raw_tail.endswith('肉'.encode('utf8')[:2]):
            value = 3.5

    return (doc, (context + text)[-120:], raw_tail), float(value)

