import re

READS = ()
WHITESPACE_TAIL = re.compile(r'(?:\\[nt]|[ \t])+$')
NBSP_TAIL = re.compile('\xa0+$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', '')
    _, position, tail, previous = carry
    token = prefix.token_strings[-1]
    value = 0.0

    if token == ':' and position == 1 and previous == 'Title':
        value = 26.656
    elif token == 'Title' and position == 0:
        value = -0.768
