        match = WHITESPACE_TAIL.search(tail)
        whitespace = match.group() if match else ''
        lines = whitespace.count('\\n')
        tabs = whitespace.count('\\t')
        if token == '\\n':
            value = min(2.9, (0.9 if previous == "\\n" else 0.52)
                        + 0.9 * (lines - 1)) if lines else 0.04
            if tabs:
                value = 1.27 + 0.5 * (tabs - 1)
            if tail.endswith('\\r'):
                value = -0.69
        elif token == '\\':
            value = min(4.5, 2.1 + (previous == "\\n")
                        + 1.0 * (lines - 1)) if lines else 0.05
            if tabs:
                value = 3.2 - 0.4 * min(tabs - 1, 2)
            if not lines and not tabs and previous.endswith('\\"'):
                value = 0.4
        elif token == ' \\':
            value = 0.9 if lines and whitespace.endswith(' ') else 0.04
        else:
            value = 2.13 if lines else 0.06
    elif (token and not token.strip('\xa0')) or token == '``':
        match = NBSP_TAIL.search(tail)
        count = len(match.group()) if match else 0
        previous_size = (len(previous)
                         if previous and not previous.strip('\xa0') else 0)
        if token == '``':
            value = -max(1.0, 4.1 - 0.13 * count) if count else 0.13
        elif len(token) == 1 and previous_size:
            # Completing short or seven-space chunks is particularly strong.
            if previous_size in (3, 7):
                value = -max(1.4, 3.7 - 0.1 * count)
            elif previous_size <= 2:
                value = -0.7 * previous_size - 0.1
            else:
                value = -0.45
        elif 1 < len(token) <= 3:
            value = -0.8 if previous_size >= 4 else 0.1
        else:
            value = -0.03 if len(token) == 1 else 0.0
