OR = {'or', 'ou', 'o', 'oder', 'или'}
MANY = {'many', 'several', 'various', 'numerous'}
COMPANIONS = {
    'friends', 'sons', 'associates', 'colleagues', 'partners',
    'family', 'things', 'stuff', 'contributors',
}


def response(token, history):
    raw = token.strip()
    w = raw.lower()
    h = history.lower().replace('\\n', '\n')
    ends = lambda pattern: bool(re.search(r'\b' + pattern + r'\s*$', h))
    last = re.search(r'(\w+|[&+])\s*$', h)
    prev = last.group(1) if last else ''
