    connected = added or alternative
    commas = min(3, h.count(',')) / 3

    if OTHER.fullmatch(w):
        v = 0.2 + 7.1 * added + 3.4 * alternative
        if connected:
            v += commas + 6.2 * (w in ('autre', 'autres'))
        v += 5.9 * (prev in ('among', 'amongst', 'entre', 'fra', 'tra', 'unter'))
        v -= 0.6 * (w == 'other' and prev in ('the', 'this', 'that'))
        v += 2.8 * (prev in MANY)
        v += 0.8 * (prev in ('all', 'any', 'some', 'few', 'two', 'three'))
        v += 2.8 * ends(r'(?:and|or|among|amongst)\s+\w+')
        v += 5.3 * ends(r'(?:and|or|among)\s+(?:many|several|various|numerous)')
        v += 4.6 * ends(r'as\s+well\s+as')
        v += 5.3 * ends(r'(?:hundreds|thousands|millions)\s+of')
        return v
    if w == 'another':
        return 0.2 + 2.1 * connected
    if w == 'etc':
        return 1.8 + 1.7 * h.rstrip().endswith(',') + 9.3 * connected
    if w == 'al' and prev == 'et':
        return 2.2
    if w in ('on', 'forth') and ends(r'(?:and|or)\s+so'):
        return 8.8
    if w == 'like' and ends(r'(?:and|or)\s+the'):
        return 9.5
    if w in ('company', 'co'):
        if added:
            return 9.5 if w == 'company' or raw[:1].isupper() else 5.8
        return 0.2
    if w in COMPANIONS and added:
        return 3.9
    if w in ('related', 'similar', 'associated', 'surrounding', 'subsequent'):
        v = 0.05 + 4.5 * added + 4.8 * alternative
        v += 3.3 * commas * connected
        v += 3.2 * ends(r'(?:and|or)\s+(?:its|their|other)')
        v += 4.2 * ends(r'(?:and|or)\s+(?:a|the|some|something)')
        return v
    if w == 'more':
        v = 0.5 * added
        if added and not ends(r'more\s+and'):
            v += 6.5 * commas
        if prev in ('many', 'much', 'few', 'lot', 'lots'):
            v += 1.1 + 7.1 * ends(r'and\s+\w+')
