    if w in ('beyond', 'elsewhere') and added:
        return 7.1 if w == 'beyond' else 5.1
    if w == 'such':
        return -0.1 + 2.8 * added + 1.3 * (prev in ('other', 'some', 'any', 'all'))
    if w in ('his', 'her', 'their', 'its') and added:
        return 0.4
