        return 9.0 if w == 'д' else 5.0
    if w == 'р' and ends(r'и\s+д'):
        return 6.0
    if w in ('等', '等等', 'など', '等相关'):
        return 1.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, (history + token)[-100:]), float(response(token, history))

