"""List-closer detector: the generic item that ends a list.

It fires on the word that closes a coordinated list with a vague "and the rest" meaning:
"X and other Y", "X or other Y", "and such", "and similar", "and more", "and beyond",
"and so on" / "so forth", "and the like", "etc", "et al", "& Co", "and friends",
"и т.д.", "等", "など", "autres". It is near 0 elsewhere.
"""
READS = ()

# how strongly the word before the candidate joins it into a list
JOINER = {"and": 1.0, "&": 1.0, "among": 1.0, "amongst": 1.0, "or": 0.5, "nor": 0.5}
# words that sit between a joiner and "other" ("and many other", "and several more")
QUANTIFIER = {"many", "several", "few", "two", "three", "various", "some", "all", "any"}

# generic words that close a list, with their typical size after a joiner
GENERIC = {
    "other": 8, "others": 7, "such": 8, "similar": 6, "beyond": 8, "related": 5,
    "surrounding": 6, "elsewhere": 5, "more": 3.5, "another": 2, "else": 2,
    "anything": 2, "something": 2, "everything": 2, "colleagues": 4, "higher": 3,
    "company": 6, "friends": 5, "associated": 5, "co": 8,
    "autres": 7, "autre": 7, "otros": 7, "otras": 7, "otro": 7, "otra": 7,
    "altre": 7, "altri": 7, "altro": 7,
}

def closer(cur, prev, prev2):
    """Closers that need no joiner: 'etc', 'et al', 'so on', 'so forth', 'the like', 'и т.д.'."""
    if cur == "etc" or cur == "等" or cur == "など":
        return 3.5
    if cur == "al" and prev == "et":
        return 2.2
    if cur in ("c", "co") and prev in ("&", "et"):
        return 8.0
    if cur == "like" and prev == "the":
        return 9.0
    if cur == "on" and prev == "so":
        return 7.0
    if cur == "forth" and prev == "so":
        return 9.0
    if cur in ("д", "п") and prev == "." and prev2 == "т":
        return 9.0
    if cur == "т" and prev == "и":
        return 3.6
    return 0.0

def step(carry, prefix, upstream):
    toks = [s.strip().lower() for s in prefix.token_strings]
    cur = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    prev2 = toks[-3] if len(toks) > 2 else ""
