            value = GENERIC[cur] * JOINER[prev]
        elif prev in QUANTIFIER and prev2 in JOINER:
            value = 0.5 * GENERIC[cur] * JOINER[prev2]   # 'and many other'
        elif prev in ("many", "several", "few", "various") and cur in ("other", "others"):
            value = 2.5                                  # 'many other'
    return carry, float(value)

