from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=32768)
def spelling(text):
    s = anyascii(text).lower()
    w = s.strip()
    return s, w, zipf_frequency(w, 'en')


def category(text, previous, word):
    s, w, frequency = spelling(text)
    ps, pw, _ = spelling(previous)
    boundary = bool(s and not s[0].isalnum())
    if '…' in text and text[:1].isspace():
        return 'ellipsis'
    if 'om' in w:
        whole = (w if boundary else word + w)[-48:]
        if 'homom' in whole:
            return 'homomorphism'
        if w.endswith(('oma', 'ome', 'omic', 'omics')):
            if frequency > 4.5:
                return 'common_word'
            return 'ome_family_initial' if boundary else 'ome_family_fragment'
        if boundary:
            return 'word_initial'
        if len(w) <= 3:
            return 'short_om'
        if w.startswith('om'):
            return 'long_om'
        return 'other_om'
    if not boundary:
        if ps.endswith('o') and w.startswith('m'):
            return 'split_om_short' if len(pw) <= 2 else 'split_om_long'
        if 'om' in pw:
            return 'continuation_short' if len(pw) <= 3 else 'continuation_long'
    return 'background'

VALUES = {
    'background': 0.0,
    'short_om': 1.24,
    'continuation_short': 0.68,
    'split_om_short': 2.0,
    'word_initial': 0.08,
    'other_om': 0.1,
    'common_word': 0.05,
    'ome_family_initial': 0.44,
    'long_om': 0.97,
    'ellipsis': 1.05,
    'continuation_long': 0.1,
    'ome_family_fragment': 2.91,
    'split_om_long': 0.25,
    'homomorphism': -4.3,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, word = '', ''
    else:
        _, previous, word = carry
    text = prefix.token_strings[-1]
    value = VALUES.get(category(text, previous, word), 0.0)
    s, w, _ = spelling(text)
    if s and not s[0].isalnum():
