WORD_CLASSES = {
    'articles': ('a an the', 4.9),
    'personal pronouns': ('i you he she it we they me him her us them', 6.3),
    'possessives': ('my your his its our their mine yours ours theirs', 1.8),
    'demonstratives': ('this that these those', 8.6),
    'prepositions': (
        'of in on at by for from with about into over under through between '
        'among without within across after before during against upon off out',
        0.3,
    ),
    'infinitival/directional to': ('to', 6.2),
    'forms of be': ('be am is are was were been being', 2.9),
    'other auxiliaries': (
        'have has had do does did can could may might will would shall should must',
        2.7,
    ),
    'conjunctions': (
        'and or but so yet nor if because although while as than whether unless '
        'since though', 2.1,
    ),
    'negation': ('not no never', 3.4),
}
WORD_HEIGHTS = {
    word: height
    for words, height in WORD_CLASSES.values()
    for word in words.split()
