"""A spelling interaction between t-bearing syllables and preceding consonants.

Short e+t and i+t fragments are positive after t, negative after j/k/g.
The same contrast occurs inside short syllables such as tet, jet and kit.
Short prefixes strengthen repetition; long prefixes and common English
words weaken the e+t case. Most other tokens are assigned zero. The colon
of a document-initial Title field has a separate, large negative response.
"""
import re
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency
import unicodedata

READS = ()

# Columns are e+t, i+t, and the weaker consonant-bridge forms (ort/ht).
CONSONANT_GAIN = {
    't': (4.3, 1.6, 1.9),
    'j': (-4.9, -3.7, 0.0),
    'k': (-2.4, -2.6, 0.0),
    'g': (-1.15, -0.9, 0.0),
}

@lru_cache(maxsize=65536)
def roman(text):
    return anyascii(text).lower()

@lru_cache(maxsize=65536)
def syllable(text):
    s = roman(text)
    if not text.isascii():
        # Retain bare Cyrillic vowel+t, not arbitrary transliterated words.
        if s not in ('et', 'it') or not all(
            'CYRILLIC' in unicodedata.name(c, '') for c in text
        ):
            return None
    m = re.fullmatch(r'([aeiou]?)([tjk])(r?)([ei])t(s)?', s.strip())
    if m:
        scale = (0.4 if m[1] else 1.0) * (0.6 if m[3] else 1.0)
        scale *= 0.65 if m[5] else 1.0
        return int(m[4] == 'i'), m[2], scale, scale
    if re.fullmatch(r't[ao]rt', s.strip()):
        return 2, 't', 1.0, 1.0
    if s != s.strip():
        return None
    if s in ('ict', 'ort', 'ht'):
        return (1, '', 1.7, 0.5) if s == 'ict' else (2, '', 1.0, 0.5)
    m = re.fullmatch(r'h?([ei])t([a-z]{0,3})', s)
    if not m:
        return None
    vowel, tail = m.groups()
    i = int(vowel == 'i')
    pos = neg = 0.0
    if not tail:
        pos = neg = 1.0
    elif tail in ('r', 'ri', 'ry', 'y', 'i', 'e'):
        pos, neg = (1.0, 1.0) if not i else (1.3, 0.25)
    elif tail == 't':
        pos = neg = 0.6
    elif tail == 's':
        pos, neg = (0.65, 0.25) if not i else (1.3, 0.7)
    elif tail in ('a', 'o', 'u'):
        pos = neg = 0.2 if not i else 0.6
    elif tail == 'en' and i:
        pos, neg = 1.2, 0.2
    elif tail == 'h':
        pos, neg = 0.7, 0.8
    elif tail == 'ed':
        pos, neg = 0.6, 0.2
    elif tail in ('er', 'her', 'ics'):
        pos = neg = 0.2
    elif tail == 'ter':
        pos = neg = 0.7
    if text[:1].isupper() and not text.isupper():
        pos *= 0.1
        neg *= 0.1
    return i, '', pos, neg


def predict(text, previous):
    spec = syllable(text)
    if spec is None:
        return 0.0
    i, onset, pos, neg = spec
    if onset:
        # Within-token versions of the same consonant/vowel/t contrast.
        base = {'t': (5.1, 1.5, 1.2), 'j': (-3.8, -2.0, 0.0),
                'k': (-0.9, -2.4, 0.0)}[onset][i]
        if text[:1].isspace():
            base += {'t': (1.5, 1.1, 0.0), 'j': (1.3, 0.0, 0.0),
                     'k': (-2.3, 1.2, 0.0)}[onset][i]
        if text.lstrip()[:1].isupper():
            base += {'t': 0.55, 'j': -1.8, 'k': -0.1}[onset]
        return pos * base
    prev = roman(previous).strip()
    if not prev:
        return pos * (3.2, 1.1, 0.0)[i]
    if prev.endswith(('t', 'th')):
        value = CONSONANT_GAIN['t'][i]
        value += (1.9, 0.7, 0.8)[i] * max(0, 3 - len(prev))
        value -= (2.1, 0.35, 0.0)[i] * max(0, min(4, len(prev) - 5))
        frequency = min(1.0, max(0.0, zipf_frequency(prev, 'en') - 4) / 3)
        value += (-1.3, 0.9, 0.0)[i] * frequency
        if previous.strip()[:1].isupper():
            value += 0.6
        return pos * value
    for consonant in ('j', 'k', 'g'):
        if prev.endswith(consonant):
            value = CONSONANT_GAIN[consonant][i]
            if prev.endswith('sk'):
                value += (0.3, -3.1, 0.0)[i]
            return neg * value
    if re.search(r'th?[aeiou]$', prev):
        return pos * (1.6, 1.4, 2.3)[i]
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, count = ('', 0) if carry is None or carry[0] != doc else carry[1:]
    text = prefix.token_strings[-1]
    value = predict(text, previous)
    if count == 1 and previous == 'Title' and text == ':':
        value = -15.18
    return (doc, text, count + 1), float(value)

