import re
from anyascii import anyascii

READS = ()
# Response to a whole stem, a stem completed across tokens, and its suffix.
ROOTS = {'astronom': (3.509, 6.048, 2.43), 'astroph': (1.435, 4.278, 0.795)}
TR_VOWELS = {'a': -0.309, 'o': 0.464}
T_R_VOWELS = {'a': -0.955, 'i': -0.239, 'o': 0.26, 'u': -0.318}


def normalize(text):
    return text.lower() if text.isascii() else anyascii(text).lower()


