    attached = bool(t and t[0].isalpha())
    if (token[:1].isupper() and not token.isupper() and
            previous[-1:].islower() and len(p.strip()) > 1):
        attached = False                 # A CamelCase word boundary.
    joined = oldword + t if attached else t
    match = re.search('[a-z]+$', joined)
    word = match.group() if match else ''
    value = 0.096 if start else 0.

    for root, (whole, split, suffix) in ROOTS.items():
        if re.match(r'\s*' + root, joined):
