        nasal = (
            (oldword.endswith('tr') and re.match(r'a[mn]|ns', t)) or
            (p.endswith(('t', 'th')) and re.match(r'ra[mn]', t)) or
            (p.strip() == 't' and t.startswith('an')) or
            (oldword.endswith('tra') and t.startswith(('m', 'n'))) or
            (oldword.endswith('tran') and t.startswith('s')))
        if nasal:
            value -= 1.566 * strength * (1. if len(t) <= 4 else .1)
        if p.endswith('tr'):
            value += strength * TR_VOWELS.get(t[0], 0.)
            if t.startswith('ue'):
