        elif p.endswith(('t', 'th')) and t.startswith('r') and len(t) > 1:
            value += strength * T_R_VOWELS.get(t[1], 0.)
        if ((p.endswith('tr') and t.startswith(('om', 'um'))) or
                (p.endswith(('t', 'th')) and t.startswith('rom'))):
            value += 1.145
        if previous.lower().endswith('str') and token[:1] in 'öÖ':
            value += 1.285

    current = t.strip()
    if current == 'strom':
        value += 1.784
    if current == 'tron':
        value += 0.7
        if oldword.endswith('synchro'):
            value += 3.3
    if current in {'sky', 'skies'}:
        value += 2.068 if current == 'sky' else 0.623
        if attached and oldword and current == 'sky':
            value -= 1.543
        if oldword in {'night', 'dark'}:
            value += 4.923
        if oldword in {'blue', 'clear', 'grey', 'gray'}:
            value += 1.487
    if current.lstrip('-') in {'body', 'bodies'}:
        if oldword in {'black', 'celestial', 'astronomical', 'heavenly',
                       'cosmic', 'water', 'central'}:
            value += 3.884
        if current.startswith('-') and oldword in {'two', 'three', 'many',
                                                  'few', 'n'}:
            value += 4.342
    if current in {'object', 'objects'} and oldword in {
            'celestial', 'astronomical', 'heavenly', 'cosmic',
            'solid', 'moving', 'tracked'}:
        value += 0.708
    if current in {'line', 'lines'} and oldword in {'straight', 'strait'}:
        value += 2.849
    if current == 'triangle' and oldword == 'right':
        value += 1.515
    if current == 'momentum' and oldword == 'angular':
        value += 2.208
    if current in {'hole', 'holes'} and oldword == 'black':
        value += 1.582
    if current in {'system', 'systems'} and p.strip() == 'solar':
        value += 0.722
    if current.startswith('tra') and len(current) <= 4:
        value -= 0.504
    return (doc, token, word[-40:]), float(value)

