"""A spelling-sensitive acoustic cue, not a general detector of sound topics.

Acoustic words and the isolated Chinese sound character give strong negative
responses. Short word pieces give smaller responses when they complete a
hard-C/K, rounded-vowel, S/ST spelling resembling 'acoustic'. The rules also
recognize -sonic and o+static. Only the unfinished word is carried forward.
"""
import re
import unicodedata
from functools import lru_cache
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=24000)
def spelling(token):
    for ch in token:
        if ch.isalpha() and not any(s in unicodedata.name(ch, '')
                                  for s in ('LATIN', 'CYRILLIC', 'GREEK')):
            return ' '
    return anyascii(token).lower()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    raw = spelling(token)
    tail = re.search('[a-z]+$', old + raw)
    word = tail.group()[-12:] if tail else ''
    value = -0.0012

    if token == '声':
        value -= 1.88
    elif token == '聲':
        value -= 4.3
    elif token == '一声':
        value -= 5.85
    elif token.endswith('一声'):
        value -= 2.84
    elif 'acoustic' in raw:
        value -= 8.97
    elif re.search(r'a[ckq]o?ust?$', word):
        value -= 8.08
    elif word.endswith(('acoustic', 'acoustics')):
        value -= 8.34
    else:
        piece = raw.strip()
        if piece.isalpha() and len(piece) <= 6:
            # A leading space breaks the word-internal spelling link.
            p = old[-4:] if raw == piece else ''
            hard_c = bool(re.search('[ckq](?![eiy])', p))
            rounded = bool(re.search('[ou]$', p))
            stem_tail = bool(re.search(r'(?:a[ctkq]|[ou]st?r?)$', p))
            velar_piece = bool(re.fullmatch(r'(?:[au][ckqg]|[ckqg][aeiou]+)',
                                     piece))
            sibilant_piece = bool(re.fullmatch(r'[aeiou]+[sz]+[trh]*[aeiou]*',
                                     piece))
            if piece == 'ac':
                value -= 0.17 + 2.55 * rounded + 0.79 * stem_tail
            elif velar_piece:
                value -= 0.37 * rounded + 0.17 * hard_c
            if sibilant_piece:
                if hard_c and piece.startswith(('u', 'ou')):
                    value -= 0.38
                if piece.startswith(('u', 'ou')) and re.search('[ckq]$', p):
                    value -= 1.18
                if 'u' not in piece and re.search('[ckq][ou]?$', p):
                    value -= 0.19
            if piece in ('ic', 'ics', 'ica', 'ico', 'yc'):
                if re.search('us?t$', p):
                    value -= 1.41
            if re.fullmatch('[iu][ckqg]', piece) and re.search('a[ckq]$', p):
                value -= 1.02
            if piece == 'static' and p.endswith('o'):
                value -= 1.67
            if piece.endswith('sonic'):
                value -= 0.67
            if raw == piece and len(piece) <= 5:
                if re.fullmatch('[aeiou]?[ckq][aeiou]*u[aeiou]*[sz]+t?', piece):
                    value -= 0.19
            if piece in ('st', 'str', 'ster'):
                if re.search('(?:[ou]|[ou][ns])$', p):
                    value -= 0.31
    return (doc, word), float(value)

