    'have has had do does did'.split()
)
QUESTIONS = set('what who whom whose which where when why how'.split())
# Python definitions/imports and package declarations often open source files.
FILE_OPENERS = {'package', 'def', 'from'}
DECLARATIONS = {'import', 'using', 'class', 'function', 'namespace', 'module'}


def initial_value(s):
    w = s.strip()
    if s.startswith('<|') and s.endswith('|>'):
        return 4.83
    if not w:
        return -4.14 if s == ' ' else 0.5
    if w.isdigit():
        return (4.6 if int(w) < 3 else 7.5) if w.isascii() else 5.8
    if w.startswith('#include'):
