    if s == '(':
        return -4.6
    if s in {'[', ':'}:
        return 0.0
    if s in FILE_OPENERS:
        return 23.5
    if s in DECLARATIONS:
        return 14.5
    if w.lower() == 'the':
        return 5.6 if s.startswith(' ') else 7.8
    if w.lower() == 'a':
        return 0.75 if s.startswith(' ') else 2.7
    if w.lower() in FUNCTION_WORDS:
        return 4.8 if s.startswith(' ') else 9.0
    if w.lower() in QUESTIONS:
        return 6.0 if s.startswith(' ') else 17.0
    if w.isalpha():
        if len(w) == 1:
            return 5.0
