DUTY_MODALS = frozenset(('should', 'shall', 'must', 'may'))
NEGATION = frozenset(('not', 'cannot', "'t"))
PERFECT = frozenset(('has', 'had', "'ve"))
THAI_TONES = frozenset('่้๊๋')
