    'dt': 0.65, 'a': 0.4, 'strong': 1.8, 'em': 0.65,
    'FONT': 1.1, 'tr': -1.1, 'details': -1.1,
    'summary': -0.5, 'sub': -0.7, 'link': -0.55, 'title': -1.0,
