"""Candidate v4: a few concepts that account for this component's large activations.

1. HTML tags. The inline tags <span>, <font> and <strong> push it up (span most strongly).
   Only the tag name counts: the word "span" inside code strings or prose is ignored.
2. Closing tags of page-structure elements (</head>, </body>, </html>, </title>, </tr>,
   </details>) push it down.
3. The Chinese characters for bell or clock (钟, 鐘, 锺) push it strongly down.
4. A repeated middle dot token (··) pushes it slightly down.
5. The digit 7 right after an escaped byte \\xa (the byte-escaped section sign \\xc2\\xa7)
   pushes it down.
Everything else predicts 0.
"""
READS = ()

INLINE_TAGS = {"span": 3.2, "font": 1.5, "strong": 2.0}
CLOSING_TAGS = {"head": -4.0, "body": -3.0, "html": -3.0, "title": -1.5, "tr": -1.0, "details": -1.5}
BELLS = {"钟", "鐘", "锺"}


def after_tag_opener(prev):
    """True if the previous token ends a tag opener: '<', '</', '><', '></'."""
    p = prev.strip()
    return p.endswith("<") or p.endswith("/")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if tok in INLINE_TAGS and after_tag_opener(prev):
        return carry, INLINE_TAGS[tok]
    if tok in CLOSING_TAGS and prev.strip() == "</":
        return carry, CLOSING_TAGS[tok]
    if tok in BELLS:
        return carry, -4.0
    if tok == "··":
        return carry, -0.25
    if prefix.token_strings[-1] == "7" and prev == "\\xa":
        return carry, -3.3
    return carry, 0.0

