            if t.startswith('yt'):
                return -2.4
            if t in ('ent','entr','enter','entre','ент','ента'):
                return 2.8
            if t in ('yst','ysts') and word.endswith('c'):
                return 5.0
            if t in ('ycl','yc') and word.endswith('c'):
                return 1.8
            if t.startswith(('ent','ент','yst','ycl')):
                return 0.7
            if t.startswith(('end','est','ell','ic','ie')):
                return 0.4
        if p.endswith(('cy','ci')) and t.startswith('t'):
            return -2.5
        if p.endswith(('cit','чит','цит')) and t[0].isalpha():
            return -2.8 if word in ('cit','чит','цит') else -1.3
        if p.endswith('cita') and t[0].isalpha():
            return -4.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, citation = '', False
    else:
        _, previous, citation = carry
    token = prefix.token_strings[-1]
    value = response(previous, token, citation)
    if '[@' in token or (previous.endswith('[') and token.startswith('@')):
        citation = True
    if ']' in token:
        citation = False
    return (doc, (previous + token)[-64:], citation), value

"""Approximate the visible m-syllable response family, especially mo4 and man4.

Isolated Chinese characters are classified by Mandarin reading and radical.
Words containing those characters respond less, except reduplications. Byte
fragments are joined so split characters can be recognized. There are smaller
responses to Japanese 'man', Korean ma syllables, and middle-dot runs.
Word-initial split characters get a small prefix response (larger for Greek),
and their completed-character response is doubled. At document starts, a fallback
uses whether the token begins with a digit, a letter, whitespace, or punctuation.
These are approximate sound/shape rules, not a model of contextual variation.
"""
import codecs
from functools import lru_cache
from pypinyin import lazy_pinyin, Style
import regex
import unihan

READS = ()

@lru_cache(maxsize=8192)
def chinese(ch):
    if not regex.fullmatch(r'\p{Script=Han}', ch):
        return 0.0
    sound = lazy_pinyin(ch, style=Style.TONE3)[0]
    number = unihan.radical(ch)
    radical = unihan.radical_name(number) if number else ''
    if sound == 'mo4':
        return 3.4
    if sound == 'man4':
        return {'water': 5.8, 'heart': 1.8}.get(radical, 0.6)
    if sound == 'meng4':
        return 2.2 if radical == 'child' else 0.55
    if sound == 'mu4' and radical in ('turban', 'earth', 'sun'):
        return 1.5
    if sound == 'mo2' and radical in ('tree', 'meat'):
        return 0.75
    if sound == 'mo3':
        return 0.8
    if sound == 'meng2':
        return 0.25
    return 0.0

@lru_cache(maxsize=32768)
def text_value(text):
    text = text.strip()
    if len(text) >= 2 and set(text) == {'·'}:
        return 1.5
    if text == 'マン':
        return 1.15
    if len(text) == 1 and '가' <= text <= '힣':
        syllable = ord(text) - ord('가')
        initial, rest = divmod(syllable, 588)
        vowel, coda = divmod(rest, 28)
        if initial == 6 and vowel == 0:  # Korean mieum + a
            # The k and ng codas give the strongest response.
            return 3.2 if coda in (1, 21) else 0.5
    core = text.rstrip('的地')
    if not core:
        return 0.0
    value = max(map(chinese, core), default=0.0)
    if len(set(core)) > 1:
        value *= 0.3
    return value

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        decoder = codecs.getincrementaldecoder('utf-8')('replace')
        previous, word_start = '', True
    else:
        _, decoder, previous, word_start = carry
    before = decoder.getstate()[0]
    text = decoder.decode(prefix.token_bytes[-1])
    after = decoder.getstate()[0]
    if not before and after:
        word_start = (text or previous or ' ')[-1].isspace()
    value = text_value(text)
    # Word-initial characters spelled over several byte tokens behave differently.
    if word_start and len(before) == 1 and len(after) == 2:
        possible = (after + b'\x80').decode('utf-8', errors='replace')
        if regex.fullmatch(r'\p{Script=Greek}', possible):
            value = 1.4
        elif regex.fullmatch(r'\p{Script=Han}', possible):
            value = 0.28
    if word_start and len(before) == 2 and not after:
        value *= 2.0
    if previous.endswith(('m', 'M')) and text in ('ont', 'ong'):
        value = 1.0
    if first and not value:
        ch = (text or ' ')[0]
        if ch.isdigit():
            value = 0.19
        elif ch.isalpha():
            value = -0.29
        elif ch.isspace():
            value = -0.12
    return (doc, decoder, text or previous, word_start), float(value)

programs.haiku:
"""Number-start detector for layers.1.mlp.down_proj:4205 (layer 1, MLP down projection).

What it responds to: the FIRST digit of a number, i.e. a digit whose previous token is not a
digit. Later digits of the same number are near zero, as is almost every other token.

How strong it is depends on what comes just before the number:
- after a comparison or equals sign, an arithmetic operator, an opening bracket, or "mod"/"Term"
  (e.g. "x = 2", "n > 3", "n^2", "(3", "-1", "mod 3"): strongest, about 0.75 to 1.1;
- after a word that introduces a quantity ("is 2", "than 3", "by 4", "to 5", "between 1"):
  high, about 0.8;
- after a plain space: medium, about 0.3 to 0.55, higher when the nearby text has maths or code
  punctuation (=, +, (, ^ and so on) and lower in prose;
- after a date or prose word ("in 1982", "June 5", "the 3", "for 2"): low, about 0.15;
- after a comma: medium, scaled by maths punctuation as for spaces;
- after a decimal point, colon or en dash (decimals, times, ranges such as "1990–1995"): near 0.

Separately, the value words "nil", "zero", "None" and "true" get a moderate value, 0.8.

The numbers come from tabulating the component's activations on training text; the program
reproduces the broad pattern rather than any table of token ids. It is a readable
approximation, not a model of the component's full computation.
"""

READS = ()

DIGITS = set("0123456789")
COMPARE = set("=<>≤≥≠")
ARITH = set("+-−*/^×÷±√_")
OPENERS = set("([{")
WEAK = set(".:–")
OPERATOR_WORDS = {"mod", "Term"}
QUANTITY_WORDS = {"is", "than", "by", "to", "be", "between", "from", "equals", "x", "of"}
DATE_WORDS = {
    "in", "on", "the", "for", "a", "In", "about", "at",
    "January", "February", "March", "April", "May", "June", "July",
    "August", "September", "October", "November", "December",
}
VALUE_WORDS = {"nil", "zero", "None", "true"}
MATH_CHARS = set("=+-*/^<>()[]{}|&_\\$")


def maths_density(strings):
    """How many maths or code punctuation characters are in the last 20 tokens before this one."""
    return min(sum(c in MATH_CHARS for c in "".join(strings[-21:-1])), 6)


def step(carry, prefix, upstream):
    s = prefix.token_strings
    tok = s[-1].strip()
    if tok in VALUE_WORDS:
        return None, 0.8
    if len(tok) != 1 or tok not in DIGITS:
        return None, 0.0
    same_doc = prefix.document_ids[-2] == prefix.document_ids[-1] if len(s) > 1 else False
    if same_doc and s[-2].strip().isdigit():
        return None, 0.05  # a later digit of a number
    before = s[-2].strip() if len(s) > 1 else ""
    if before in COMPARE or before in OPERATOR_WORDS:
        return None, 1.1
    if before in ARITH or before in OPENERS:
        return None, 0.75
    if before == "":
        word = s[-3].strip() if len(s) > 2 else ""
        if word in QUANTITY_WORDS:
            return None, 0.8
        if word in DATE_WORDS:
            return None, 0.15
        return None, 0.3 + 0.05 * maths_density(s)
    if before == ",":
        return None, 0.3 + 0.05 * maths_density(s)
    if before in WEAK:
        return None, 0.05
    return None, 0.35

programs.sol:
"""Recognize four-digit, year-like numbers, especially 1970--2019.

Emit a positive pulse on their fourth digit, weaker for older or future years
and for numbers attached to punctuation or identifiers. Round centuries are
weaker. Smaller rules cover indentation, conclusion words, and document starts,
including a large response to the colon in an opening ``Title:`` header.
All state is local to the current document.
"""
READS = ()


def year_response(year):
    if not 1500 <= year < 2100:
        return -0.035
    if year < 1750:
        return 0.04
    if year < 1800:
        return 0.25
    if year < 1910:
        return 0.42 if year < 1900 else 0.33
    if year < 1930:
        return 0.63
    if year < 1960:
        return 0.88
    if year < 1970:
        return 1.0
    if year < 2020:
        return 1.22
    if year < 2040:
        return 0.8
    return 0.3


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '', 0)
    _, run, before, tail, position = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if position == 0:
        value = -0.2 if token.startswith(' ') else -0.1
    if token.isascii() and token.isdigit():
        if not run:
            before = tail[-1:]
        run = (run + token)[:5]
        if len(run) == 4:
            year = int(run)
            value = year_response(year)
            if year % 100 == 0 and value > 0:
                value *= 0.4
            if before in ('.', ',', ':', '/', '-'):
                value *= 0.7
            elif before.isascii() and before.isalpha():
                value *= 0.5
        elif len(run) >= 3:
            value = -0.01
    else:
        run = ''
        if token == ' ':
            if tail.endswith('\\n'):
                value = -0.65
            elif tail.endswith('\n'):
                value = -0.32
        word = token.strip()
        if word == 'Therefore':
            value = 0.37 if tail.endswith('\n') else 0.19
        elif word in {'So', 'Thus', 'Hence', 'Now'} and tail.endswith('\n'):
            value = 0.14
        if position == 0 and token == '<|endoftext|>':
            value = 0.894
        elif position == 0 and token == 'Title':
            value = -1.44
        elif position == 1 and tail == 'Title' and token == ':':
            value = 9.24
    tail = (tail + token)[-16:]
    return (doc, run, before, tail, position + 1), value

programs.haiku:
"""Layer-1 MLP unit 4208 (down_proj) responds negatively to sub-word pieces that
spell a b-sound followed by r (through a vowel): "ber" in "Kim|ber|ly", "Ber|lin",
"ember" in "ember-cli", "iber", "umber", "chamber", "bir", "bor", "bur", and the
Cyrillic and Arabic equivalents "бер" and "بر". Whole common words that contain the
same letters (number, member, born, bird, October, Robert) stay at zero. It also has
a constant positive value on the repeated filler token "··". Everything else is zero.
Values are typical activations of each piece, in the unit's own scale."""

READS = ()

# Piece -> typical activation (leading space = the piece starts a word).
BR_PIECES = {
    "ber": -2.5, " ber": -2.6, " Ber": -2.7, "Ber": -2.7, "BER": -2.7,
    "bers": -2.0, "ember": -3.2, "amber": -5.0, "umber": -2.2, "iber": -3.4,
    " chamber": -2.8, " Chamber": -4.0, "bir": -4.0, " bir": -0.5, " Bir": -0.9,
    "bor": -2.6, " bor": -1.1, " Bor": -1.5, "bur": -2.0, " bur": -0.7, " Bur": -0.8,
    "bert": -1.0, " aber": -1.0, "aber": -4.0, "uber": -1.6, " haber": -2.4,
    " fiber": -1.8, " timber": -2.1, "br": -0.8, "bour": -2.0,
    "бер": -4.0, " бер": -3.4, "بر": -3.0, " بر": -1.5,
}
# Whole words that contain the same letters, and so do not fire.
WHOLE_WORDS = {"number", "numbers", "member", "members", "born", "birth", "bird", "robber"}

def value(token, prev):
    if token == "··":
        return 1.4
    if token.strip().lower() in WHOLE_WORDS:
        return 0.0
    return BR_PIECES.get(token, 0.0)

def step(carry, prefix, upstream):
    return carry, value(prefix.token_strings[-1], None)

programs.sol:
"""A partial explanation using local infinitive and article cues.

'To' opening a clause, and 'to' after coordination, are negative; ordinary
verb-to combinations are near zero. Articles depend on the preceding
function word or verb class. Scandinavian articles are more negative.
Two exceptional document openings, numeral 12 and a space-prefixed period,
have large negative responses. Other positions default to zero.
State is reset at each document boundary.
"""
import re
import wordnet
from functools import lru_cache

READS = ()
COPULAS = set('is are was were be been being'.split())
COORDINATORS = set('and or but nor'.split())
SCANDINAVIAN = set(
    'och att är på av för inte det til og som med har var ikke men'.split()
)


@lru_cache(maxsize=2048)
def verb_roots(word):
    return set(wordnet.base_forms(word)) | {word}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, recent, opening = '', '', ''
    else:
        _, previous, recent, opening = carry
    token = prefix.token_strings[-1]
    word = previous.strip().lower()
    boundary = (not previous or '\n' in previous or previous.isspace()
                or previous.rstrip().endswith(('.', '!', '?')))
    opening = (opening + token) if opening is not None else None
    if opening is not None and (len(opening) > 3 or not opening.isdecimal()):
        opening = None
    value = 0.0
    if not previous and token == ' .':
        value = -1.83
    elif opening == '12':
        value = -3.25
    elif token.lstrip(' \"“') in ('to', 'To'):
        if word in COORDINATORS:
            value = -0.64
        elif word in COPULAS:
            value = -0.19
        elif word in ('not', 'as'):
            value = -0.23
        elif boundary:
            value = -0.40 if token == ' To' else -0.35
        elif word in (',', ';', ':', '-', '–', '—'):
            value = -0.28
    elif token in (' a', ' an', ' A', ' An', 'A', 'An', 'a', 'an'):
        capital = token.strip()[0].isupper()
        if boundary:
            value = -0.24 if capital else -0.16
        elif capital:
            value = 0.14
        elif token.startswith(' '):
            roots = verb_roots(word)
            if word in COPULAS or 'have' in roots:
                value = 0.08
            elif roots & {'make', 'become', 'find'}:
                value = 0.20
            elif roots & {'use', 'show', 'illustrate'}:
                value = -0.29
            elif word in ('as', 'like', 'without'):
                value = 0.12
            elif word in ('through', 'after', 'before', 'following'):
                value = -0.25
            elif word in ('to', 'from', 'by', 'over', 'that', 'which'):
                value = -0.12
            elif word in ('in', 'on', 'of', 'with', 'for', 'and', 'or'):
                value = -0.045
            elif word == ',':
                value = -0.10
    elif token in (' ett', ' ein', ' Ein', ' egy'):
        value = (-0.90 if token == ' ett' else
                 -0.67 if token == ' egy' else -0.32)
    elif token in (' en', ' et', ' En', ' Et'):
        words = re.findall(r'[^\W\d_]+', recent.lower())
        if sum(w in SCANDINAVIAN for w in words) >= 2:
            value = -0.85
    return (doc, token, (recent + token)[-160:], opening), value

programs.haiku:
"""Clause-opening function words, a rare but strong negative signal.

Mostly near zero. Its clearest behaviour is negative on words that open an
infinitive or a noun phrase at the start of a clause: "... and to ...",
"or to", "is to", sentence-initial "To" and "A", and indefinite articles in
other languages (ein, een, ett, egy, su). The English article "a" is
negative after a preposition or an instrument verb ("by a", "using a",
"through a") and positive after a linking verb or "have/make" ("is a",
"as a", "make a"). The first token of a row is mildly positive. Otherwise 0.
"""
READS = ()

CONJ = {" and", " or", " but", " And", " Or", " But"}
BREAK = {".", "\n", ".\n", "\n\n", ",", "<|endoftext|>", ")."}
FOREIGN_INDEF = {" ein", " Ein", " een", " ett", " egy", " su", " sus", " sa", " votre"}
PREP_OR_INSTRUMENT = {" of", " in", " by", " using", " use", " uses", " through", " via", " after",
                      " over", " from", " that", " or", " when", " if", " than", " for", " on", " to",
                      " showing", " shows", " ;", ";", ":", ","}
LINKING = {" is", " was", " be", " been", " being", " are", " as", " have", " has", " had",
           " make", " made", " making", " become", " became", " becomes", " find", " found", " it", " not"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    if len(toks) == 1:
        return carry, 0.11
    prev = toks[-2]
    if cur in (" to", " To", "To"):
        if prev in CONJ:
            return carry, -0.6
        if prev in BREAK or prev in (" is", " was", " as", " that", " not"):
            return carry, -0.35 if cur != " to" else -0.25
        return carry, 0.0
    if cur in (" A", "A", " a"):
        if cur == " a":
            if prev in LINKING:
                return carry, 0.08
            if prev in PREP_OR_INSTRUMENT:
                return carry, -0.1
            return carry, 0.0
        if prev in BREAK:
            return carry, -0.2
        return carry, 0.0
    if cur in FOREIGN_INDEF:
        return carry, -0.3
    return carry, 0.0

programs.sol:
"""Pulses on vowel clusters at word beginnings, especially rare spellings.

Join split UTF-8 characters. Track an initial run of vowels, restarting at punctuation, whitespace, or a
camel-case boundary. A following vowel fragment gives a positive response;
English fragment frequency downweights familiar spellings. There are smaller
script-specific rules and negative responses to Thai vowel carriers,
Japanese long-vowel spellings, Chinese author labels, and long middot runs.
This approximates the sparse responses, not all contextual variation.
"""
import codecs
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
VOWELS = set('aeiouyаеёиоуыэюяαεηιουω')
GREEK_DIPHTHONGS = {'αι', 'ει', 'οι', 'ου', 'αυ', 'ευ', 'ηυ', 'υι'}


@lru_cache(maxsize=4096)
def plain(s):
    return ''.join(c for c in unicodedata.normalize('NFD', s.lower())
                   if not unicodedata.combining(c))


def step(carry, prefix, upstream):
    fresh = (carry is None or len(prefix.document_ids) < 2 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    onset, last, previous, dots, pending = (
        ('', '', '', 0, b'') if fresh else carry
    )
    raw = pending + prefix.token_bytes[-1]
    text, used = codecs.utf_8_decode(raw, 'replace', False)
    pending = raw[used:]
    s = text.strip()
    first = plain(text[:1])
    value = -0.001

    if (onset and len(onset) <= 3 and last.isalpha()
            and first in VOWELS and first != 'y'):
        before = plain(onset[-1])
        if (before in 'aeiouy' and first in 'aeiou'
                and not (text[0].isupper() and not text.isupper())):
            frequency = zipf_frequency(onset + text, 'en')
            if before == 'i':
                value = 1.8 if frequency < 2.5 else 0.65
            elif before == 'u':
                value = 1.5 if frequency < 3 else 0.8
            elif before == 'e':
                value = 1.0 if frequency < 3 else 0.15
            elif before == 'o' and first == 'o' and frequency < 2.5:
                value = 1.0
            elif before == 'y' and first == 'u' and frequency < 2.5:
                value = 2.0
        elif before in 'иу' and first in 'аеёиоуыэюя':
            value = 2.5 if zipf_frequency(onset + text, 'ru') < 3 else 0.2
        elif before == first == 'о':
            value = 1.0
        elif before in 'αεηιουω' and first in 'αεηιουω':
            if before + first not in GREEK_DIPHTHONGS:
                value = 2.0

    # Greek ou is the written vowel /u/, also within longer words.
    if plain(previous) == 'ου' and first in set('αεηιουω'):
        value = max(value, 1.3)
    if (len(previous) == 1 and plain(previous) == 'ι'
            and previous != 'ι' and first in set('αεηιουω')):
        value = max(value, 1.3)

    if s == 'อ':
        value = -2.1
    elif previous == 'อ' and s and 'THAI' in unicodedata.name(s[0], ''):
        value = -2.0
    if previous in {'ア', 'オ'} and text.startswith('ー'):
        value = -1.5
    elif previous == 'ウ' and text.startswith('ー'):
        value = 1.5
    elif previous == 'お' and s == 'き':
        value = -1.1
    elif previous == 'う' and s == 'え':
        value = 1.6
    elif previous in {'ウ', 'ヴ', 'フ'} and s[:1] in set('ァィゥェォ'):
        value = 3.0
    if s == '作者':
        value = -3.3
    elif previous == '作者' and s in {':', '：'}:
        value = -0.5
    if ((fresh or previous == '<|endoftext|>')
            and s in {'function', 'var', 'window'}):
        value = 2.0

    dots = dots + len(s) if s and set(s) == {'·'} else 0
    if dots >= 16:
        value = -0.75

    for c in text:
        if c.isalpha():
            if c.isupper() and last.islower():
                onset = ''
            if plain(c) not in VOWELS:
                onset = None
            elif onset is not None:
                onset = (onset + c)[-24:]
        elif not unicodedata.combining(c):
            onset = ''
        last = c
    # Conservative pulse amplitudes reduce false positives on partial words.
    if value > 0:
        value *= 0.6
    return (onset, last, s if text else previous, dots, pending), value

"""Lexical pulses for locale codes, package/path prefixes and text boundaries.

Language and country abbreviations are especially negative when punctuation or
an import, language field or URL makes them look like codes rather than word
endings. These may be prefixes of longer names too; no future token is read.
Chinese locales can span multiple tokens. A few formatting delimiters
have positive pulses. Everything else is left near zero.
"""
import re
import pycountry

READS = ()
CODES = {c.alpha_2.lower() for c in pycountry.countries}
CODES.update(
    language.alpha_2 for language in pycountry.languages
    if hasattr(language, 'alpha_2')
)
FILE_SUFFIXES = {'py', 'rs', 'go', 'js', 'ts', 'cs', 'sh', 'md'}
PACKAGE_CODES = {
    'br': -4.1, 'cn': -2.2, 'de': -4.5, 'uk': -3.5, 'id': -2.6,
}
PATH_CODES = {'en': -2.5, 'it': -5.2, 'pt': -2.1, 'ar': -2.6, 'es': -1.5}


def pulse(token, before):
    if token == '<|endoftext|>':
        return -1.92
    if len(token) >= 2 and set(token) == {'·'}:
        return 0.67
    if token == ':' and re.search(r'(?:^|<\|endoftext\|>)Title$', before):
        return 3.18
    if token == ':' and before.endswith('localhost'):
        return 2.6
    if token == '::' and re.search(r'\buse[^\n;]{0,60}$', before):
        return 1.3
    if token == '\tat':
        return -1.0
    if token == '/java':
        return -2.3
    if token in ('/org', '/com', '/net', '/io'):
        return -1.1
    declaration = bool(re.search(r'\b(?:import|package)\s*$', before))
    if declaration and token.strip() in ('com', 'org', 'net', 'io'):
        return -0.9 if token.strip() == 'com' else -0.2

    # Split pieces of zh-CN, zh-TW, zh-Hans and en-US.
    if token == '-CN' and re.search(r'zh(?:-Hans)?$', before):
        return -6.5
    if token == '-US' and before.endswith('en'):
        return -4.1
    if token in ('-H', '-T') and before.endswith('zh'):
        return -3.25
    if token == 'W' and before.endswith('zh-T'):
        return -4.4

    match = re.fullmatch(r'([ ./_=,:\-]*)([a-zA-Z]{2})', token)
    if not match:
        return 0.0
    lead, code = match[1], match[2].lower()
    if code not in CODES:
        return 0.0
    if not lead and before and before[-1].isalnum():
        return 0.0  # A suffix inside a word, not the start of a code.
    if lead == '.' and code in FILE_SUFFIXES:
        return 0.0
    if re.search(r'(?:iso[ _-]*(?:3166(?:-1)?|639)|\bp):$', before, re.I):
        return -2.1
    if declaration:
        return PACKAGE_CODES.get(code, -0.1)
    if not lead and re.search(r'https?://$', before):
        if code == 'en':
            return -5.3
        return -2.5 if code == 'ar' else -0.7
    language_field = re.search(
        r'(?:lang|locale|language)[^\n]{0,100}$', before, re.I
    )
    if language_field and not lead.isspace():
        if code == 'en':
            return -6.0
        return -5.3 if code == 'zh' else -0.1
    if '/' in lead or (not lead and before.endswith('/')):
        if code == 'pt' and re.search(r'//\S*$', before):
            return -6.0
        return PATH_CODES.get(code, -0.2)
    if '.' in lead or (not lead and before.endswith('.')):
        return -0.15
    delimited = lead.strip() or (
        not lead and before and before[-1] in ':_="\'[('
    )
    if code == 'zh' and (lead or delimited):
        if lead.isspace():
            return -3.4 if match[2] == 'zh' else -0.2
        return -5.0
    if delimited:
        return -0.7 if code == 'en' else -0.08
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = pulse(token, before)
    return (doc, (before + token)[-180:]), value

"""A sparse approximation: medicine spellings positive, thin/tight negative.

Medical nouns and medicine characters get positive values. Split medical
roots and drug-like endings also contribute. The negative rules cover tight,
thin, tin, and short i/u/r syllables following 'th'. Most tokens get zero.
A trailing word and unfinished UTF-8 bytes cross token boundaries; both
are reset at a document boundary. Many other activations are not modeled.
"""
import codecs
import re
from functools import lru_cache
from anyascii import anyascii
import wordnet

READS = ()

@lru_cache(maxsize=32768)
def is_drug(word):
    return wordnet.is_a(word, 'drug')

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', '', '')
    _, pending, before, last = carry
    raw = pending + prefix.token_bytes[-1]
    text, used = codecs.utf_8_decode(raw, 'replace', False)
    s = anyascii(text).lower()
    match = re.search('[a-z]+$', s)
    word = match[0] if match else ''
    continuation = bool(before and s and s[0].isalpha())
    if continuation and match and match.start() == 0:
        word = (before + word)[-64:]
    t = s.strip()
    value = 0.0

    # Literal medicine vocabulary: not a general detector of medical topics.
    if t in ('medicine', 'medicines', 'medicinal'):
        value += 4.2
    elif t == 'medication':
        value += 2.5
    elif t == 'medications':
        value += 1.5
    elif t in ('drug', 'drugs'):
        value += 0.55
    elif t in ('medic', 'medics'):
        value += 1.4
    elif t in ('pharmac', 'pharma', 'pharmacy'):
        value += 0.7
    elif continuation:
        if re.fullmatch('medicin(?:e|es|al)', word):
            value += 8.0
        elif re.fullmatch('medecin(?:e|es)?', word):
            value += 3.2
        elif word.startswith('meditsi') and not before.startswith('meditsi'):
            value += 5.0
        elif 'medic' in word and 'medic' not in before:
            value += 2.2

    # The corresponding written medicine signs, including split characters.
    if text and text[-1] in '药藥':
        value += 5.0
    elif any(ch in text for ch in '药藥'):
        value += 2.5
    if '薬' in text:
        value += 11.0
    if '약' in text:
        value += 8.0 if pending else (5.0 if text == '약' else 2.0)
    if last.endswith(('药', '藥', '薬', '약')) and text in ('品', '物', '품'):
        value += 1.8

    # Drug names and chemical suffixes, only when attached to an earlier token.
    if continuation:
        if t.endswith(('ine', 'ines', 'in', 'ins', 'cin', 'ide', 'ides')):
            if not before.endswith('t'):
                value += 1.5 * is_drug(word)
        if t.endswith(('illin', 'illins')):
            value += 2.0
        if t in ('icide', 'icides', 'cide', 'cides', 'cidal', 'idine'):
            value += 1.2
        if t in ('idal', 'ide', 'ides') and before.endswith('ic'):
            value += 4.0
        if t in ('in', 'ins', 'inous') and before.endswith('c'):
            value += 0.7

    # A separate negative spelling family.
    if t == 'tight':
        value -= 5.5
    elif t == 'tightly':
        value -= 2.5
    elif t in ('tighter', 'tighten', 'tightens', 'tightening'):
        value -= 2.0
    elif t in ('thin', 'thinner', 'thinly'):
        value -= 1.0
    elif t in ('tin', 'tung'):
        value -= 1.2

    # Short th+i/u/r continuations (as in thin, Thun, Mithra), not
    # arbitrary continuations such as lithium, epithet or withRegistry.
    syllable = re.fullmatch(
        r'(?:[iu][b-df-hj-np-tv-z]{1,2}[ae]?|r[a-z]{0,2})', t
    )
    if continuation and before.endswith('th') and syllable:
        if not before.endswith('with') or text.isupper():
            value -= 2.6 if before.endswith('ith') else 0.8

    return (doc, raw[used:], word, text), float(value)

programs.haiku:
"""Word-level detector for two lexical families that drive this MLP unit.

Positive: the medicine family. A word being typed that contains "medicin"
(medicine, medicines, medicinal, biomedicine) gives a large positive value; the
other medicine forms (medication, medicament, medicina) and the Chinese words for
medicine (药, 中药) give a smaller or similar one; the stem "medic" on its own
(the first piece of "medicine" split across tokens) gives a moderate value.
Negative: the word "tight" and its compounds (airtight, watertight), a strong
negative; "tightly", "tighter", "tighten" a weaker one; "thin" and a few
th-in look-alikes a weak one.
Everything else is 0. The word is the run of Latin letters typed so far, so the
program follows a word across subword pieces; a document boundary resets it.
"""
import re

READS = ()

LETTERS_AT_END = re.compile(r"[a-z]*$")
CHINESE = {"药": 5.5, "中药": 6.0}
THIN_LIKE = {"thin": -2.0, "thyme": -3.5, "tin": -1.0, "twin": -1.0}


def value_of_word(word, token):
    if token in CHINESE:
        return CHINESE[token]
    if "medicin" in word or "medicament" in word:
        return 4.5
    if "medication" in word:
        return 2.0
    if word == "medic":
        return 2.4
    if word == "tight" or word.endswith("tight"):
        return -6.5
    if word.startswith("tight"):
        return -2.0
    return THIN_LIKE.get(word, 0.0)


def step(carry, prefix, upstream):
    word, doc = carry if carry is not None else ("", None)
    if prefix.document_ids[-1] != doc:
        word = ""
    token = prefix.token_strings[-1]
    word = LETTERS_AT_END.search((word + token).lower()).group(0)
    value = value_of_word(word, token)
    return (word, prefix.document_ids[-1]), value

programs.sol:
"""A sparse response to document openings and stereotyped text/code phrases.

The largest response is the colon in an opening ``Title:`` label. Other
negative responses mark SQL constraints, type declarations, and familiar web
boilerplate. Ordinary text gets zero. A small opening-token estimate uses
case, digits, whitespace, and comment punctuation rather than token IDs.
An uninterrupted repetition of the opening token keeps its opening estimate.
This approximates large observed spikes, not all contextual variation.
"""
READS = ()

# Literal phrase endings: SQL, sequence-reference pages, code, and web menus.
PHRASES = (
    (' NOT NULL', -1.3),
    (' not null', -0.4),
    (' OEIS', -1.6),
    ('Sequence in context', -3.6),
    ('Defined in', -2.0),
    ('| Templates', -2.7),
    ('scientific notation', -1.5),
    ('(strict_types', -2.3),
    ('sys/types', -1.8),
    ('<inttypes', -4.9),
    ('<reference types', -3.0),
    ('Toggle navigation', -2.8),
    ('navigation, search', -3.2),
    ('Related Links', -2.4),
    ('Related searches', -2.4),
    ('Definition Classes', -0.85),
)


def opening(token):
    """Coarse estimate where the model has no preceding text to attend to."""
    if token == '\x00':
        return 2.55
    if token and set(token) == {'·'}:
        return -0.79
    if token == '//\n':
        return -8.55
    if token == '<!':
        return -6.85
    if token == '\r':
        return -4.75
    if token == r'\t':
        return -2.34
    if token == r'\n':
        return -1.46
    if '\xa0' in token and token.isspace():
        return -0.8 - 0.23 * len(token)
    if token.isspace():
        if '\n' in token:
            return 0.15
        return -0.67 if token == '\t' else -0.3
    if token.startswith("'''"):
        return 2.0
    if token.startswith('"""'):
        return 0.95
    if token.startswith('#') or token in ('/*', '/*\n', '/*\r\n'):
        return 0.43
    word = token.strip()
    if word.isascii() and word.isalpha():
        if len(word) == 1 and word.isupper():
            return 0.36
        if word[0].isupper():
            return 0.3
        return 0.17
    if word.isdigit():
        return -0.09
    if any(c.isalpha() for c in word):
        return 0.09
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, text, repeated, first = 0, '', True, token
    else:
        _, position, text, repeated, first = carry
        position += 1
        repeated = repeated and token == first
    text = (text + token)[-100:]
    value = opening(token) if position == 0 or repeated else 0.0
    if position == 1 and text == 'Title:':
        value = -15.43
    elif position == 1 and text == '12':
        value = -2.37
    elif position > 0:
        for ending, amplitude in PHRASES:
            if text.endswith(ending):
                value = amplitude
                break
    return (doc, position, text, repeated, first), value

"""A sparse approximation of a Chinese fixed-expression response.

Idioms (including three-character beginnings), classical four-character
words, balanced repetitions, collective 都 subjects, and 越来越 comparisons
receive negative values. Other four-character dictionary words get a weaker
negative default. Unambiguous completion/persistence adverbs get positive values. Other rules cover document openings and Title:/issue tags.
Most tokens return zero; individual lexical exceptions are not memorized.
"""
from functools import lru_cache
import regex
import cedict

READS = ()


def idiom_beginnings():
    """Three-character starts of four-character CC-CEDICT idioms."""
    definitions, words = cedict._table()
    return frozenset(
        word[:3] for word, entries in words.items()
        if len(word) == 4 and regex.fullmatch(r'\p{Script=Han}+', word)
        and any('idiom' in definitions[i] for i in entries)
    )


IDIOM_STARTS = idiom_beginnings()


@lru_cache(maxsize=8192)
def word_value(text):
    if not regex.fullmatch(r'\p{Script=Han}+', text):
        return 0.0
    n = len(text)
    if n < 2:
        return 0.0
    glosses = cedict.glosses(text)
    if n == 2:
        persistent = any(g.startswith('still') or 'as before' in g
                         for g in glosses)
        if 'already' in glosses or (persistent and 'or' not in glosses):
            return 0.30
        return 0.0
    if text.endswith('都') and ('人' in text or
                               text.startswith(('大家', '一切', '所有'))):
        return -1.15
    if text.startswith(('越来越', '愈来愈')):
        return -0.80
    if n == 3:
        if text in IDIOM_STARTS:
            return -1.0
        numerals = '一二三四五六七八九十'
        if text[1] in '对比' and text[0] in numerals and text[2] in numerals:
            return -1.20
        return 0.0
    if n == 4 and glosses and any(c in text for c in '而之以既俱'):
        return -1.25
    if any('idiom' in gloss for gloss in glosses):
        return -0.85
    balanced = n == 4 and (text[0] == text[2] or
                          (text[0] == text[1] and text[2] == text[3]))
    if balanced and not any('abbr.' in g for g in glosses):
        return -0.85
    return -0.30 if glosses and n == 4 else 0.0


def opening_value(text):
    if text == 'Title':
        return 0.14
    if text == '<|im_start|>':
        return 0.41
    if text == '<':
        return 0.74
    if text == '\t':
        return -0.76
    if regex.fullmatch(r'\p{Script=Han}{2}', text):
        return 0.45
    word = text.strip()
    if word.isascii() and word.isalpha() and word.istitle():
        return -0.38
    return 0.0


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or doc != carry[0]:
        position, recent = 0, ''
    else:
        position, recent = carry[1] + 1, carry[2]
    value = opening_value(text) if position == 0 else word_value(text)
    if position == 1 and recent == 'Title' and text == ':':
        value = -3.56
    elif text == 'issue' and recent.endswith('<issue_start><'):
        value = -1.73
    elif position == 1 and recent == '<' and text == 'issue':
        value = -0.25
    recent = (recent + text)[-32:]
    return (doc, position, recent), value

programs.haiku:
"""Component layers.1.mlp.down_proj:4220 (v3): the document-start response.

This component is mostly a small, token-specific signal, and nothing simple
predicts its sign across ordinary text. Its clearest systematic response is at
the first token of a document, where the model resets attention. A document
starts either at the first token of a row (the row was cut from a longer
text) or right after an <|endoftext|> inside the row. We predict a fixed value
per kind of first token there, and 0 at every other position.
"""
import unicodedata

READS = ()

# Mid-row document starts (right after <|endoftext|>): by kind of first token.
AFTER_ENDOFTEXT = {
    "capital_word": -0.35,   # capitalised English word, e.g. "The", "Click"
    "lower_word": -0.09,     # lowercase English word, e.g. "using"
    "cjk": 0.20,             # Chinese characters
    "special": 0.41,         # special tokens such as <|im_start|>
    "punct": 0.03,
    "other": -0.22,          # mixed scripts, symbols, etc.
}
# First token of a row: almost nothing, except Chinese characters.
ROW_START = {"cjk": 0.29}


def kind(s):
    if s.startswith("<|"):
        return "special"
    body = s.strip()
    if not body:
        return "other"
    if all("一" <= ch <= "鿿" for ch in body):
        return "cjk"
    if all(ch.isascii() and ch.isalpha() for ch in body):
        return "capital_word" if body[0].isupper() else "lower_word"
    if all(unicodedata.category(ch).startswith(("P", "S")) for ch in body):
        return "punct"
    return "other"


def step(carry, prefix, upstream):
    t = prefix.position
    k = kind(prefix.token_strings[-1])
    if t == 0:
        return carry, float(ROW_START.get(k, 0.0))
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, float(AFTER_ENDOFTEXT.get(k, 0.0))
    return carry, 0.0

programs.sol:
"""A sparse detector of opening/escaped syntax and Chinese locative endings.

Most ordinary tokens get zero. Positive rules recognize square-bracket
openings, literal metacharacters after backslashes, and Chinese tokens ending
in 在. Java static imports have the opposite sign. Document-initial rules
cover some question/declaration starts and punctuation; formatting rules cover
front matter and repeated punctuation. State is only recent text
document position, and whether the document starts with YAML front matter.
This is only a partial approximation; many token-specific responses, especially
at document beginnings, are left at zero.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, count, front = '', 0, False
    else:
        _, tail, count, front = carry
    s = prefix.token_strings[-1]
    word = s.strip()
    if count == 0:
        front = word == '---'
    elif front and tail.endswith('\n') and word == '---':
        front = False
    value = 0.0

    # Chinese locative/progressive constructions, not following complements.
    if '在' in word:
        if word.startswith('在') and len(word) > 1:
            value = -0.14
        elif word.endswith('在'):
            value = 0.25
            if word in ('正在', '是在'):
                value = 0.4
            if word == '在':
                value = 0.05
            elif word in ('现在', '現在'):
                value = 0.11 if word == '现在' else 0.30
            elif word.endswith('存在'):
                value = 0.13
            elif word[:-1] in ('都', '也', '还', '就', '一直', '就是'):
                value = 0.65
        elif word.startswith('存在'):
            value = 0.08

    # A bare opening bracket is different from indexing an identifier.
    if '[' in s and ']' not in s:
        if s.rstrip().endswith('['):
            before = s.rstrip()[:-1].strip()
            if before:
                value = 0.14
                if before in ('(', '=', ':', '"', "'", '&'):
                    value = 0.32
                if before.endswith('^'):
                    value = 1.0
                if before.endswith('.'):
                    value = 0.05
            else:
                value = -0.025
                if tail.rstrip().endswith(':'):
                    value = 0.21
                elif tail.rstrip().endswith('{'):
                    value = 0.45
                elif tail.endswith(('\"\\', "'\\")):
                    value = 0.73
                elif tail.endswith('(\n'):
                    value = 0.65
                elif tail.endswith('\n') and not s.startswith(' '):
                    value = 0.25
                elif tail.rstrip().endswith(('"/', "'/")):
                    value = 0.8
            if '\n' in s:
                value = 0.25
        elif word.endswith('[^'):
            value = 0.75
        elif word.startswith('[{'):
            value = -0.4
        elif word.startswith('['):
            value = -0.055
    if word.startswith('^') and tail.endswith('['):
        value = 0.8

    # Literal punctuation and multiple levels of string escaping.
    if word and set(word) == {'\\'}:
        n = len(word)
        if n >= 3:
            value = min(1.2, 0.29 * n)
        elif n == 2:
            value = 0.07
        elif tail.endswith(('[', '#[', ' \\', '\\\\')):
            value = 0.65
    if word.startswith('\\'):
        if word.startswith('\\"') and tail.endswith('\\\\'):
            value = 1.45 if word == '\\"' else 0.7
        elif word == '\\[':
            value = 0.28
        elif word in ('\\$', '\\_', '\\<'):
            value = 0.25
        elif word in ('\\.', '\\/'):
            value = 0.65
    if tail.endswith('\\') and word and word[0] in '*!':
        value = 0.8

    # A few recognizable programming and document headers.
    if word == 'static':
        if re.search(r'\bimport\s*$', tail):
            value = -2.8
        elif re.search(r'\b(public|protected|internal)\s*$', tail):
            value = -0.18
    if word == '(' and '\n' in s and re.search(r'(?:^|\n)import$', tail):
        value = 0.85
    if re.search(r'#!?\[$', tail) and word.isidentifier():
        value = 0.12
        if word == 'serde':
            value = 0.6
        elif word in ('feature', 'plugin'):
            value = 0.75
    if front and tail.endswith('\n') and word in ('title', 'author', 'date'):
        value = 1.0
    if count == 0:
        if s in ('What', 'How'):
            value = -1.15
        elif s in ('A', 'An'):
            value = -0.42
        elif s in ('int', 'type', 'function', 'var', 'const', 'using'):
            value = 0.78
        elif s == '\"':
            value = 0.85
        elif s == ';':
            value = 0.73
        elif s == '//\n':
            value = 11.74
    if s == '··':
        value = 1.38
    if s == '\r' and not tail.strip('\r'):
        value = 8.0

    return (doc, (tail + s)[-96:], count + 1, front), float(value)

"""Sparse lexical approximation of an early multilingual MLP feature.

It is strongly negative on Chinese 'quite/very' (挺), and more mildly
negative on several degree expressions, Korean morphemes, and Japanese
polite endings. Chinese necessity/difficulty expressions have the opposite
sign. Separate rules cover fullness ideographs, selected local phrases,
code openings, a leading NUL, and middle-dot decoration. A small opening
offset handles unrecognized non-numeric initial tokens; elsewhere the
default is zero.
All state resets at document boundaries. The rules summarize measured
lexical patterns, not a general sentiment detector; many responses remain
unmodeled.
"""
from opencc import OpenCC

READS = ()
SIMPLIFY = OpenCC('t2s').convert

# Chinese modal expressions: inability, necessity, and difficulty.
MODALS = {
    '不由': 3.0, '不得': 1.9, '不如': 1.8,
    '不容易': 1.0, '难得': 1.7,
    '很难': 1.0, '难以': 0.8,
    '值得': 0.8, '不能': 0.35, '必须': 0.6,
    '顺': 0.8, '几乎': 0.8, '只能': 0.55, '不可': 0.35,
    '让人': 0.8, '给人': 0.7,
}
EVALUATIONS = {
    '还不错': -1.0,
    '还好': -1.2, '算是': -1.0,
    '满分': -1.0,
}
NEGATIVE_KOREAN = {'안': -2.6, '못': -3.1}
CODE_OPENINGS = {
    'def', 'function', 'const', 'var', 'class', 'using', 'import', 'export',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    previous, tail, byte_tail = ('', '', b'') if fresh else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip()
    if not word.isascii():
        word = SIMPLIFY(word)
    raw = prefix.token_bytes[-1]
    completed = (byte_tail + raw).decode('utf-8', 'ignore')[-1:]
    boundary = fresh or token[:1].isspace() or previous[-1:].isspace()
    value = 0.0

    if word == '挺':
        value = -15.5
    elif word == '还挺':
        value = -10.0
    elif word == '挺好':
        value = -5.0
    elif word in MODALS:
        value = MODALS[word]
        if word == '不得' and tail.endswith(('得', '的')):
            value = 5.3
        if word == '必须' and tail.endswith(('你', '我', '他')):
            value = 2.5
    elif word in EVALUATIONS:
        value = EVALUATIONS[word]
    elif word == '些' and tail.endswith('有'):
        value = -0.85
    elif word == '别' and tail.endswith(('但', '也', '可', '千萬', '千万')):
        value = -1.0
    elif word == '人':
        value = 0.1
        if tail.endswith('可'):
            value = -1.8
        elif tail.endswith(('这', '那')):
            value = -1.5
    elif word == '行' and tail.endswith(('也', '不', '还', '還')):
        value = -1.5
    elif word == '快' and tail.endswith(('你', '我', '他')):
        value = -1.2
    elif word == '命' and tail.endswith('不要'):
        value = 1.5
    elif word == '得' and tail.endswith(('真', '没')):
        value = 4.0 if tail.endswith('没') else 1.5
    elif word == '顿' and tail.endswith('一'):
        value = 1.0
    elif word == '怪' and tail.endswith('都'):
        value = -6.0
    elif word == '超':
        technical = any(x in tail for x in (
            '超导', '超導', '电缆', '電纜', '高温', '高溫',
        ))
        value = 0.05 if technical else -0.8
    elif word in NEGATIVE_KOREAN and boundary:
        value = NEGATIVE_KOREAN[word]
    elif token == ' 않':
        value = -1.4
    elif token == ' 하':
        value = -0.6
    elif word == '만':
        numeric = previous.strip().isdigit() or tail.endswith(('천', '백', '억'))
        value = -1.3 if numeric else -2.8
        if tail.endswith('하지'):
            value = 0.0
    elif word == '되':
        value = -2.4 if token.startswith(' ') else -1.4
    elif word == '넘':
        value = -3.5
    elif word == '참' and boundary:
        value = -2.6
    elif token in {' 들', ' 너무', ' 매우', ' 가능'}:
        value = -0.95
    elif token in {'았다', '며'}:
        value = -0.7
    elif word in {'ます', 'おります'}:
        value = -0.4
        if tail.endswith(('くれ', 'れて', 'てい', 'かね')):
            value = -1.0
    elif word == 'う' and tail.endswith('も'):
        value = -1.8
    elif word == 'な' and tail.endswith(('も', 'に')):
        value = -0.45
    elif word == 'guys' and previous.strip().lower() == 'you':
        value = -3.5
    elif token == ' just':
        value = -0.14
    elif token == ' must':
        value = -0.11

    # Complete a split UTF-8 ideograph before recognizing 'full'.
    split_fullness = token == '\ufffd' and completed in {'满', '滿', '満'}
    if word in {'满', '満'} or split_fullness:
        value = -1.8
    if fresh and value == 0.0 and not word.isdigit():
        single_letter = len(word) == 1 and word.isascii() and word.isalpha()
        value = 0.4 if single_letter else 0.2
    if token == '··':
        value = 1.6
    if fresh and token in CODE_OPENINGS:
        value = 1.9 if token in {'const', 'function', 'var'} else 1.2
    if fresh and token == '<!':
        value = -3.8
    if fresh and token == '\x00':
        value = 4.8
    if fresh and token.startswith('/*'):
        value = 1.9
    if token == '<|im_start|>':
        value = 0.1
    return (doc, token, (tail + token)[-24:], (byte_tail + raw)[-8:]), value
